#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CertificatePdfArchiveMetadata {
    pub archive_format: &'static str,
    pub font_embedding: &'static str,
    pub embedded_fonts: &'static [&'static str],
    pub embedded_font_sha256: &'static [&'static str],
    pub font_version: &'static str,
    pub font_license: &'static str,
    pub output_intent: &'static str,
}

pub const fn certificate_pdf_archive_metadata() -> CertificatePdfArchiveMetadata {
    CertificatePdfArchiveMetadata {
        archive_format: CERTIFICATE_PDF_ARCHIVE_FORMAT,
        font_embedding: CERTIFICATE_PDF_FONT_EMBEDDING,
        embedded_fonts: &CERTIFICATE_PDF_EMBEDDED_FONTS,
        embedded_font_sha256: &CERTIFICATE_PDF_FONT_SHA256,
        font_version: CERTIFICATE_PDF_FONT_VERSION,
        font_license: CERTIFICATE_PDF_FONT_LICENSE,
        output_intent: CERTIFICATE_PDF_OUTPUT_INTENT,
    }
}

/// The immutable, finalized data used to render a documentation certificate PDF.
///
/// `steps` is authoritative and is rendered in exactly the supplied order. `evidence` must be
/// the already filtered and `relative_path`-sorted slice used for the finalized evidence
/// manifest. The renderer validates those invariants but deliberately does not re-evaluate,
/// filter, or sort either slice.
pub struct CertificatePdfSnapshot<'a> {
    pub track: &'a TrackRecord,
    pub automation: &'a TrackAutomation,
    pub profile: &'a Profile,
    pub steps: &'a [StepState],
    pub evidence: &'a [&'a EvidenceItem],
    pub deviations: &'a [BlockingDeviation],
    pub revision_references: &'a [String],
    pub certificate_id: &'a str,
    pub finalized_at: &'a str,
    pub certificate_version: &'a str,
    pub sha256sums_sha256: &'a str,
    pub evidence_manifest_sha256: &'a str,
    pub markdown_certificate_sha256: &'a str,
    pub finalization_timestamp: FinalizationTimestampSnapshot,
    /// Derived, in-memory render assets. Their source evidence remains untouched
    /// and the renderer validates that every asset still names registered
    /// artwork evidence before using it.
    pub artwork_previews: &'a [CertificateArtworkPreview],
    pub render_options: CertificateRenderOptions,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StatusTone {
    Success,
    Notice,
    Neutral,
    Error,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct OverviewFact {
    label: &'static str,
    value: String,
    tone: StatusTone,
    localize_value: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct OverviewGroup {
    title: &'static str,
    facts: Vec<OverviewFact>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProviderResponseSummary {
    response: String,
    api_version: String,
    response_is_system: bool,
    api_version_is_system: bool,
}

/// Normalized, language-independent presentation model shared by the German
/// and English summary/overview renderers. Technical detail sections continue
/// to consume the same immutable snapshot and never recompute a different data
/// source for either language.
struct CertificateViewModel<'a> {
    snapshot: &'a CertificatePdfSnapshot<'a>,
    groups: Vec<OverviewGroup>,
    final_artwork: Option<&'a EvidenceItem>,
    final_artwork_preview: Option<&'a CertificateArtworkPreview>,
    provider_response: ProviderResponseSummary,
    open_blocking_deviations: usize,
    workflow_pass_count: usize,
    workflow_na_count: usize,
}

impl<'a> CertificateViewModel<'a> {
    fn from_snapshot(snapshot: &'a CertificatePdfSnapshot<'a>) -> Self {
        let evidence_values = snapshot
            .evidence
            .iter()
            .map(|item| (*item).clone())
            .collect::<Vec<_>>();
        let production_coverage =
            workflow::subscription_production_coverage(snapshot.track, &evidence_values);
        let generation_coverage =
            workflow::subscription_generation_coverage(snapshot.track, &evidence_values);
        let fields = &snapshot.track.fields;
        let external = &snapshot.track.audio_screening.external;
        let local = &snapshot.track.audio_screening.local;
        let open_blocking_deviations = snapshot
            .deviations
            .iter()
            .filter(|deviation| deviation.blocking && !deviation.resolved)
            .count();
        let final_artwork = snapshot
            .evidence
            .iter()
            .copied()
            .find(|item| item.role == EvidenceRole::FinalArtwork);
        let final_artwork_preview = snapshot
            .artwork_previews
            .iter()
            .find(|preview| preview.role == EvidenceRole::FinalArtwork);
        let terms_exist = snapshot
            .evidence
            .iter()
            .any(|item| item.role == EvidenceRole::SunoTermsRights);
        let generative_ai_documented = fields.generative_ai_used.is_some();
        let disclosure = match fields.generative_ai_used {
            Some(false) => OverviewFact::neutral("Disclosure documented", "N/A"),
            Some(true) => match fields.audio_disclosure_applied {
                Some(DocumentationAnswer::Yes | DocumentationAnswer::No) => {
                    OverviewFact::success("Disclosure documented", "DOCUMENTED")
                }
                Some(DocumentationAnswer::NotDocumented) | None => {
                    OverviewFact::notice("Disclosure documented", "NOT DOCUMENTED")
                }
            },
            None => OverviewFact::notice("Disclosure documented", "NOT DOCUMENTED"),
        };

        let groups = vec![
            OverviewGroup {
                title: "TRACK",
                facts: vec![
                    OverviewFact::documented_neutral(
                        "Final generation",
                        &fields.suno_final_generation_date,
                    ),
                    OverviewFact::documented_neutral("Suno model", &fields.suno_model),
                    OverviewFact::documented_neutral("Suno plan", &fields.suno_plan_at_generation),
                    OverviewFact::neutral_system(
                        "Commercial use intended",
                        yes_no(Some(fields.commercial_use_intended)),
                    ),
                ],
            },
            OverviewGroup {
                title: "INTEGRITY",
                facts: vec![
                    if snapshot.automation.release_identical_to_suno_export {
                        OverviewFact::success("Release = Suno final export", "SHA-256 MATCH")
                    } else {
                        OverviewFact::error("Release = Suno final export", "SHA-256 MISMATCH")
                    },
                    OverviewFact::neutral("Evidence files", snapshot.evidence.len().to_string()),
                    if open_blocking_deviations == 0 {
                        OverviewFact::success("Blocking deviations", "0")
                    } else {
                        OverviewFact::error(
                            "Blocking deviations",
                            open_blocking_deviations.to_string(),
                        )
                    },
                ],
            },
            OverviewGroup {
                title: "RIGHTS EVIDENCE",
                facts: vec![
                    coverage_overview_fact("Production period covered", production_coverage),
                    coverage_overview_fact("Final generation covered", generation_coverage),
                    if terms_exist {
                        OverviewFact::success("Terms archived", "DOCUMENTED")
                    } else {
                        OverviewFact::notice("Terms archived", "NOT DOCUMENTED")
                    },
                ],
            },
            OverviewGroup {
                title: "AI TRANSPARENCY",
                facts: vec![
                    if generative_ai_documented {
                        OverviewFact::success("Generative AI documented", "DOCUMENTED")
                    } else {
                        OverviewFact::notice("Generative AI documented", "NOT DOCUMENTED")
                    },
                    disclosure,
                    if final_artwork.is_some() {
                        OverviewFact::success("Artwork documented", "DOCUMENTED")
                    } else {
                        OverviewFact::notice("Artwork documented", "NOT AVAILABLE")
                    },
                ],
            },
            OverviewGroup {
                title: "AUDIO SCREENING",
                facts: vec![
                    screening_overview_fact("Chromaprint", local.status),
                    screening_overview_fact("ACRCloud", external.status),
                    OverviewFact::neutral(
                        "Coverage",
                        format!("{:.2} %", external.track_coverage_percent),
                    ),
                    OverviewFact::neutral(
                        "Unique samples",
                        external.unique_sample_count.to_string(),
                    ),
                ],
            },
            finalization_timestamp_overview_group(&snapshot.finalization_timestamp),
        ];
        let workflow_pass_count = snapshot
            .steps
            .iter()
            .filter(|step| step.status == StepStatus::Pass)
            .count();
        let workflow_na_count = snapshot
            .steps
            .iter()
            .filter(|step| step.status == StepStatus::NotApplicable)
            .count();

        Self {
            snapshot,
            groups,
            final_artwork,
            final_artwork_preview,
            provider_response: consolidated_provider_response(external),
            open_blocking_deviations,
            workflow_pass_count,
            workflow_na_count,
        }
    }
}

fn finalization_timestamp_overview_group(
    timestamp: &FinalizationTimestampSnapshot,
) -> OverviewGroup {
    let provider = if timestamp.provider.trim().is_empty() {
        "NOT DOCUMENTED"
    } else {
        timestamp.provider.as_str()
    };
    let configuration = match timestamp.provider_configuration_status {
        TimestampProviderConfigurationStatus::Ready => OverviewFact::success(
            "Provider configuration",
            provider_configuration_status_label(timestamp.provider_configuration_status),
        ),
        TimestampProviderConfigurationStatus::Disabled
        | TimestampProviderConfigurationStatus::NotConfigured => OverviewFact::notice(
            "Provider configuration",
            provider_configuration_status_label(timestamp.provider_configuration_status),
        ),
        _ => OverviewFact::error(
            "Provider configuration",
            provider_configuration_status_label(timestamp.provider_configuration_status),
        ),
    };
    let technical = match timestamp.technical_status {
        ExternalTimestampStatus::Verified => OverviewFact::success(
            "Technical status",
            provider_verification_status_label(timestamp.technical_status),
        ),
        ExternalTimestampStatus::VerificationFailed
        | ExternalTimestampStatus::AnchorMismatch
        | ExternalTimestampStatus::UnsupportedResponse => OverviewFact::error(
            "Technical status",
            provider_verification_status_label(timestamp.technical_status),
        ),
        _ => OverviewFact::notice(
            "Technical status",
            provider_verification_status_label(timestamp.technical_status),
        ),
    };
    let metadata = timestamp.provider_metadata.as_ref();
    let protocol = metadata
        .map(|value| value.protocol.as_str())
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("NOT DOCUMENTED");
    let qualification = metadata
        .and_then(|value| value.qualification.as_ref())
        .map(|value| value.eidas_qualification_status)
        .unwrap_or(TimestampQualificationStatus::NotChecked);
    let qualification = if qualification == TimestampQualificationStatus::QualifiedServiceVerified {
        OverviewFact::success(
            "Provider qualification",
            "eIDAS QUALIFIED TRUST SERVICE – VERIFIED",
        )
    } else {
        OverviewFact::notice(
            "Provider qualification",
            qualification_status_label(qualification),
        )
    };

    OverviewGroup {
        title: "EXTERNAL TIMESTAMP",
        facts: vec![
            OverviewFact::neutral("Provider", provider),
            configuration,
            technical,
            OverviewFact::neutral("Protocol", protocol),
            qualification,
        ],
    }
}

impl OverviewFact {
    fn success(label: &'static str, value: impl Into<String>) -> Self {
        Self {
            label,
            value: value.into(),
            tone: StatusTone::Success,
            localize_value: true,
        }
    }

    fn notice(label: &'static str, value: impl Into<String>) -> Self {
        Self {
            label,
            value: value.into(),
            tone: StatusTone::Notice,
            localize_value: true,
        }
    }

    fn neutral(label: &'static str, value: impl Into<String>) -> Self {
        Self {
            label,
            value: value.into(),
            tone: StatusTone::Neutral,
            localize_value: false,
        }
    }

    fn neutral_system(label: &'static str, value: impl Into<String>) -> Self {
        Self {
            label,
            value: value.into(),
            tone: StatusTone::Neutral,
            localize_value: true,
        }
    }

    fn documented_neutral(label: &'static str, value: &str) -> Self {
        if value.trim().is_empty() {
            Self::neutral_system(label, "NOT DOCUMENTED")
        } else {
            Self::neutral(label, value)
        }
    }

    fn error(label: &'static str, value: impl Into<String>) -> Self {
        Self {
            label,
            value: value.into(),
            tone: StatusTone::Error,
            localize_value: true,
        }
    }
}

fn coverage_overview_fact(label: &'static str, status: workflow::CoverageStatus) -> OverviewFact {
    match status {
        workflow::CoverageStatus::Yes => OverviewFact::success(label, "COMPLETE"),
        workflow::CoverageStatus::No => OverviewFact::error(label, "NOT COVERED"),
        workflow::CoverageStatus::NotVerified => OverviewFact::notice(label, "NOT VERIFIED"),
    }
}

fn screening_overview_fact(label: &'static str, status: AudioScreeningStatus) -> OverviewFact {
    let value = audio_screening_status_label(status);
    match status {
        AudioScreeningStatus::FingerprintGenerated | AudioScreeningStatus::NoMatchDetected => {
            OverviewFact::success(label, value)
        }
        AudioScreeningStatus::MatchDetected => OverviewFact::notice(label, value),
        AudioScreeningStatus::NotRun | AudioScreeningStatus::SkippedNotConfigured => {
            OverviewFact::notice(label, value)
        }
        _ => OverviewFact::error(label, value),
    }
}

fn consolidated_provider_response(
    external: &AudioScreeningExternalRecord,
) -> ProviderResponseSummary {
    let values = external
        .samples
        .iter()
        .map(|sample| {
            (
                sample.provider_status_code,
                nonempty(sample.provider_status_message.as_deref()),
                nonempty(sample.provider_api_version.as_deref()),
            )
        })
        .collect::<Vec<_>>();
    let Some(first) = values.first().copied() else {
        return ProviderResponseSummary {
            response: "N/A".into(),
            api_version: "N/A".into(),
            response_is_system: true,
            api_version_is_system: true,
        };
    };
    if values.iter().any(|value| *value != first) {
        return ProviderResponseSummary {
            response: "MULTIPLE — see Technical Appendix".into(),
            api_version: "MULTIPLE — see Technical Appendix".into(),
            response_is_system: true,
            api_version_is_system: true,
        };
    }
    let response = match (first.0, first.1) {
        (Some(code), Some(message)) => format!("{code} · {message}"),
        (Some(code), None) => code.to_string(),
        (None, Some(message)) => message.to_owned(),
        (None, None) => "N/A".into(),
    };
    ProviderResponseSummary {
        response,
        api_version: first.2.unwrap_or("N/A").to_owned(),
        response_is_system: first.0.is_none() && first.1.is_none(),
        api_version_is_system: first.2.is_none(),
    }
}

/// A bounded, CMYK render derivative of one verified artwork evidence item.
///
/// The bytes are never written beside the evidence and never replace its
/// registered path or SHA-256. They exist only long enough to serialize the PDF.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CertificateArtworkPreview {
    role: EvidenceRole,
    evidence_id: String,
    file_name: String,
    relative_path: String,
    sha256: String,
    width_pixels: u32,
    height_pixels: u32,
    cmyk_pixels: Arc<Vec<u8>>,
    resource_id: String,
}

impl CertificateArtworkPreview {
    fn xobject_id(&self) -> XObjectId {
        XObjectId(self.resource_id.clone())
    }
}

/// Build bounded artwork render assets from verified evidence without writing
/// to the track tree. A missing, undecodable, path-mismatched, or hash-mismatched
/// optional image is skipped so certificate generation retains its textual
/// fallback and never weakens the registered evidence identity.
pub fn prepare_artwork_previews(
    track_root: &Path,
    evidence: &[&EvidenceItem],
) -> Vec<CertificateArtworkPreview> {
    const ARTWORK_ROLES: [EvidenceRole; 6] = [
        // High-resolution summary roles come first so byte-identical process
        // evidence reuses the 640 px derivative, never the 384 px derivative.
        EvidenceRole::FinalArtwork,
        EvidenceRole::ReleaseArtwork,
        EvidenceRole::ArtworkSunoOriginal,
        EvidenceRole::AiArtworkOriginal,
        EvidenceRole::AiArtworkEdited,
        EvidenceRole::HumanEditedArtwork,
    ];

    let mut previews: Vec<CertificateArtworkPreview> = Vec::new();
    for role in ARTWORK_ROLES {
        let Some(item) = evidence.iter().copied().find(|item| item.role == role) else {
            continue;
        };
        let Some(expected_sha256) = item.sha256.as_deref() else {
            continue;
        };
        let Some(source_path) = resolve_preview_source(track_root, item, expected_sha256) else {
            continue;
        };
        let Ok(source_metadata) = std::fs::symlink_metadata(&source_path) else {
            continue;
        };
        if !source_metadata.file_type().is_file()
            || source_metadata.file_type().is_symlink()
            || source_metadata.len() != item.size_bytes
            || source_metadata.len() > ARTWORK_SOURCE_MAX_FILE_BYTES
        {
            continue;
        }
        let Ok(source_bytes) = std::fs::read(&source_path) else {
            continue;
        };
        if source_bytes.len() as u64 != item.size_bytes
            || !crate::security::sha256_bytes(&source_bytes).eq_ignore_ascii_case(expected_sha256)
        {
            continue;
        }
        if let Some(existing) = previews
            .iter()
            .find(|preview| preview.sha256.eq_ignore_ascii_case(expected_sha256))
            .cloned()
        {
            previews.push(CertificateArtworkPreview {
                role,
                evidence_id: item.id.clone(),
                file_name: item.file_name.clone(),
                relative_path: item.relative_path.clone(),
                sha256: expected_sha256.to_ascii_lowercase(),
                width_pixels: existing.width_pixels,
                height_pixels: existing.height_pixels,
                cmyk_pixels: existing.cmyk_pixels,
                resource_id: existing.resource_id,
            });
            continue;
        }
        let Ok(mut reader) =
            image::ImageReader::new(Cursor::new(source_bytes)).with_guessed_format()
        else {
            continue;
        };
        let mut limits = image::Limits::default();
        limits.max_image_width = Some(ARTWORK_SOURCE_MAX_DIMENSION);
        limits.max_image_height = Some(ARTWORK_SOURCE_MAX_DIMENSION);
        limits.max_alloc = Some(ARTWORK_SOURCE_MAX_ALLOCATION);
        reader.limits(limits);
        let Ok(decoded) = reader.decode() else {
            continue;
        };
        let maximum_pixels = if matches!(
            role,
            EvidenceRole::FinalArtwork | EvidenceRole::ReleaseArtwork
        ) {
            ARTWORK_PREVIEW_MAX_PIXELS
        } else {
            ARTWORK_PROCESS_PREVIEW_MAX_PIXELS
        };
        let thumbnail = decoded.resize(maximum_pixels, maximum_pixels, FilterType::Lanczos3);
        let rgba = thumbnail.to_rgba8();
        let (width_pixels, height_pixels) = rgba.dimensions();
        if width_pixels == 0 || height_pixels == 0 {
            continue;
        }
        let cmyk_pixels = rgba_to_cmyk_on_white(rgba.as_raw());
        previews.push(CertificateArtworkPreview {
            role,
            evidence_id: item.id.clone(),
            file_name: item.file_name.clone(),
            relative_path: item.relative_path.clone(),
            sha256: expected_sha256.to_ascii_lowercase(),
            width_pixels,
            height_pixels,
            cmyk_pixels: Arc::new(cmyk_pixels),
            resource_id: format!("SunoDMArtwork{:02}", previews.len() + 1),
        });
    }
    previews
}

fn resolve_preview_source(
    track_root: &Path,
    item: &EvidenceItem,
    expected_sha256: &str,
) -> Option<PathBuf> {
    let relative = Path::new(&item.relative_path);
    if let Ok(path) = crate::security::contained_path(track_root, relative, true) {
        return Some(path);
    }

    // Historical case-only path inconsistencies are not corrected in-place.
    // A preview may use a unique byte-identical sibling solely as a render
    // source; the displayed identity remains the immutable registered path.
    let parent = relative.parent()?;
    let directory = crate::security::contained_path(track_root, parent, true).ok()?;
    let expected_extension = relative
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or_default();
    let mut matches = std::fs::read_dir(directory)
        .ok()?
        .filter_map(std::result::Result::ok)
        .filter_map(|entry| {
            let file_type = entry.file_type().ok()?;
            if !file_type.is_file() || file_type.is_symlink() {
                return None;
            }
            let path = entry.path();
            let metadata = entry.metadata().ok()?;
            let extension = path
                .extension()
                .and_then(|extension| extension.to_str())
                .unwrap_or_default();
            if metadata.len() != item.size_bytes
                || metadata.len() > ARTWORK_SOURCE_MAX_FILE_BYTES
                || !extension.eq_ignore_ascii_case(expected_extension)
            {
                return None;
            }
            crate::security::sha256_file(&path)
                .ok()
                .filter(|digest| digest.eq_ignore_ascii_case(expected_sha256))
                .map(|_| path)
        });
    let unique = matches.next()?;
    matches.next().is_none().then_some(unique)
}

fn rgba_to_cmyk_on_white(rgba: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(rgba.len());
    for pixel in rgba.chunks_exact(4) {
        let alpha = u32::from(pixel[3]);
        let red = ((u32::from(pixel[0]) * alpha + 255 * (255 - alpha)) / 255) as u8;
        let green = ((u32::from(pixel[1]) * alpha + 255 * (255 - alpha)) / 255) as u8;
        let blue = ((u32::from(pixel[2]) * alpha + 255 * (255 - alpha)) / 255) as u8;
        let black = 255_u8.saturating_sub(red.max(green).max(blue));
        if black == 255 {
            output.extend_from_slice(&[0, 0, 0, 255]);
            continue;
        }
        let denominator = u32::from(255 - black);
        let cyan = ((u32::from(255 - red - black) * 255) / denominator) as u8;
        let magenta = ((u32::from(255 - green - black) * 255) / denominator) as u8;
        let yellow = ((u32::from(255 - blue - black) * 255) / denominator) as u8;
        output.extend_from_slice(&[cyan, magenta, yellow, black]);
    }
    output
}

/// Immutable input for a post-finalization external-timestamp addendum.
///
/// This deliberately borrows only display strings plus the factual three-state hash comparison. It
/// has no reference to a mutable track or to phase-one evidence, so rendering an addendum cannot
/// silently re-evaluate or mutate the finalized certificate snapshot.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ExternalTimestampPdfSnapshot<'a> {
    /// The human-facing ID of the original, immutable technical certificate.
    pub certificate_id: &'a str,
    pub provider: &'a str,
    pub timestamp_type: &'a str,
    pub timestamp_value: &'a str,
    pub referenced_artifact: &'a str,
    pub referenced_artifact_path: &'a str,
    pub referenced_sha256: &'a str,
    pub actual_sha256: &'a str,
    pub referenced_hash_match: Option<bool>,
    pub evidence_file_name: &'a str,
    pub evidence_sha256: &'a str,
    pub imported_at: &'a str,
    pub provenance: &'a str,
    pub external_reference_id: &'a str,
    pub provider_verification_url: &'a str,
    pub note: &'a str,
    /// Present only for an automatically obtained provider response. A missing
    /// value deliberately retains the legacy, manually recorded addendum path.
    pub provider_metadata: Option<&'a TimestampProviderMetadata>,
}

/// Render a deterministic, standalone PDF for evidence attached after technical finalization.
///
/// The original manifest, Markdown certificate, and certificate PDF remain byte-identical. The
/// caller is responsible for publishing and hashing this returned addendum as a separate phase-two
/// artifact.
pub fn generate_external_timestamp_addendum_pdf(
    snapshot: &ExternalTimestampPdfSnapshot<'_>,
) -> Result<Vec<u8>> {
    validate_external_timestamp_snapshot(snapshot)?;

    let mut layout = PdfLayout::new(CertificateRenderOptions::default());
    layout.write_wrapped(
        "SunoDM – External Timestamp Evidence Addendum",
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        14.0,
        BuiltinFont::HelveticaBold,
        1.28,
    );
    layout.write_wrapped(
        "Post-finalization technical timestamp and provider-qualification evidence",
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        7.5,
        BuiltinFont::Helvetica,
        1.2,
    );
    layout.y_mm -= 1.0;
    layout.rule(LEFT_MM, RIGHT_MM, layout.y_mm, 0.6);
    layout.y_mm -= 3.0;

    layout.section_title("External Timestamp Evidence");
    let rows = external_timestamp_rows(snapshot);
    // Keep the complete provenance/verification labels searchable with the
    // bundled DejaVu metrics; long provider values may wrap in the value column.
    layout.table_rows(&rows, 112.0);
    layout.section_title("Provider Trust and Qualification");
    let qualification_rows = external_timestamp_qualification_rows(snapshot);
    layout.table_rows(&qualification_rows, 112.0);
    layout.write_wrapped(
        EXTERNAL_TIMESTAMP_DISCLAIMER,
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        8.0,
        BuiltinFont::Helvetica,
        1.35,
    );
    layout.write_wrapped(
        if snapshot.provider_metadata.is_some() {
            "Technical timestamp verification and provider qualification answer different questions. A higher qualification is shown only when the archived independent trust record verifies it for the relevant timestamp time; no legal-effect or rights determination is made."
        } else {
            "Legacy manually recorded timestamp evidence: provider and timestamp values were supplied by the user and were not promoted to provider verification. No qualified timestamp, legal effect, or rights determination is asserted."
        },
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        8.0,
        BuiltinFont::Helvetica,
        1.35,
    );

    let deterministic_id = format!("{}:{}", snapshot.certificate_id, snapshot.evidence_sha256);
    let (pages, _) = layout.into_pages(snapshot.certificate_id);
    let mut document = PdfDocument::new("SunoDM – External Timestamp Evidence Addendum");
    document.metadata.info.creator = GENERATED_BY.to_owned();
    document.metadata.info.producer = GENERATED_BY.to_owned();
    document.metadata.info.subject =
        "Post-finalization external timestamp evidence addendum".to_owned();
    document.metadata.info.identifier = snapshot.certificate_id.to_owned();
    document.metadata.info.keywords = vec![
        "SunoDM".to_owned(),
        "external timestamp".to_owned(),
        "evidence".to_owned(),
        "SHA-256".to_owned(),
    ];
    document.with_pages(pages);
    serialize_pdfa_2b(document, &deterministic_id, snapshot.imported_at, "en-US")
}

fn validate_external_timestamp_snapshot(snapshot: &ExternalTimestampPdfSnapshot<'_>) -> Result<()> {
    for (label, value) in [
        ("certificate ID", snapshot.certificate_id),
        ("referenced artifact", snapshot.referenced_artifact),
        (
            "referenced artifact path",
            snapshot.referenced_artifact_path,
        ),
        ("evidence filename", snapshot.evidence_file_name),
        ("import timestamp", snapshot.imported_at),
        ("provenance", snapshot.provenance),
    ] {
        if value.trim().is_empty() {
            return Err(AppError::Data(format!(
                "External timestamp PDF snapshot has no {label}."
            )));
        }
    }
    for (label, digest) in [
        ("referenced artifact", snapshot.referenced_sha256),
        ("actual referenced artifact", snapshot.actual_sha256),
        ("timestamp evidence", snapshot.evidence_sha256),
    ] {
        validate_sha256(label, digest)?;
    }
    for (label, value) in [
        ("certificate ID", snapshot.certificate_id),
        ("provider", snapshot.provider),
        ("timestamp type", snapshot.timestamp_type),
        ("timestamp value", snapshot.timestamp_value),
        ("referenced artifact", snapshot.referenced_artifact),
        (
            "referenced artifact path",
            snapshot.referenced_artifact_path,
        ),
        ("evidence filename", snapshot.evidence_file_name),
        ("external reference ID", snapshot.external_reference_id),
        (
            "provider verification URL",
            snapshot.provider_verification_url,
        ),
        ("note", snapshot.note),
        ("import timestamp", snapshot.imported_at),
        ("provenance", snapshot.provenance),
    ] {
        validate_win_ansi(label, value)?;
    }
    if let Some(metadata) = snapshot.provider_metadata {
        if !metadata.provider_response_sha256.trim().is_empty() {
            validate_sha256(
                "timestamp provider response",
                metadata.provider_response_sha256.as_str(),
            )?;
        }
        for (label, value) in [
            ("timestamp provider adapter", metadata.adapter.as_str()),
            ("timestamp provider protocol", metadata.protocol.as_str()),
            (
                "timestamp provider request algorithm",
                metadata.request_algorithm.as_str(),
            ),
            (
                "timestamp provider response format",
                metadata.response_format.as_str(),
            ),
            (
                "timestamp provider endpoint identifier",
                metadata.provider_endpoint_identifier.as_str(),
            ),
            (
                "timestamp provider response archive",
                metadata.provider_response_file_name.as_str(),
            ),
            (
                "timestamp referenced revision ID",
                metadata.referenced_revision_id.as_str(),
            ),
            ("timestamp provider issuer", metadata.issuer.as_str()),
            (
                "timestamp provider certificate subject",
                metadata.certificate_subject.as_str(),
            ),
            (
                "timestamp provider certificate serial number",
                metadata.certificate_serial_number.as_str(),
            ),
            (
                "timestamp provider policy OID",
                metadata.policy_oid.as_str(),
            ),
            (
                "timestamp verification timestamp",
                metadata.verification_timestamp.as_str(),
            ),
            (
                "timestamp verification message",
                metadata.verification_message.as_str(),
            ),
        ] {
            validate_win_ansi(label, value)?;
        }
        validate_timestamp_qualification_metadata(metadata)?;
    }
    Ok(())
}

fn validate_timestamp_qualification_metadata(metadata: &TimestampProviderMetadata) -> Result<()> {
    const QUALIFIED_TIMESTAMP_SERVICE_TYPE_URI: &str =
        "http://uri.etsi.org/TrstSvc/Svctype/TSA/QTST";
    const QUALIFIED_SERVICE_GRANTED_STATUS_URI: &str =
        "http://uri.etsi.org/TrstSvc/TrustedList/Svcstatus/granted";

    if !metadata.certificate_sha256.trim().is_empty() {
        validate_sha256("timestamp signer certificate", &metadata.certificate_sha256)?;
    }
    if !metadata.provider_response_sha256.trim().is_empty() {
        validate_sha256(
            "timestamp provider response",
            &metadata.provider_response_sha256,
        )?;
    }
    for digest in &metadata.trust_anchor_sha256 {
        validate_sha256("timestamp trust anchor", digest)?;
    }

    let Some(qualification) = metadata.qualification.as_ref() else {
        return Ok(());
    };
    let identity = &qualification.identity;
    if !identity.certificate_sha256.trim().is_empty() {
        validate_sha256(
            "qualified timestamp signer certificate",
            &identity.certificate_sha256,
        )?;
    }
    if !metadata.certificate_sha256.trim().is_empty()
        && !identity.certificate_sha256.trim().is_empty()
        && !metadata
            .certificate_sha256
            .eq_ignore_ascii_case(&identity.certificate_sha256)
    {
        return Err(AppError::Data(
            "Certificate PDF timestamp qualification identity does not match the cryptographically verified signer certificate."
                .into(),
        ));
    }

    for (label, value) in [
        (
            "qualification check timestamp",
            qualification.checked_at.as_str(),
        ),
        ("qualification detail", qualification.message.as_str()),
        (
            "qualification certificate subject",
            identity.certificate_subject.as_str(),
        ),
        (
            "qualification certificate issuer",
            identity.certificate_issuer.as_str(),
        ),
        (
            "qualification certificate serial number",
            identity.certificate_serial_number.as_str(),
        ),
        ("qualification policy OID", identity.policy_oid.as_str()),
        (
            "qualification identity service identifier",
            identity.service_identifier.as_str(),
        ),
        (
            "Trust Service Provider",
            qualification.trust_service_provider.as_str(),
        ),
        ("Trust Service", qualification.trust_service_name.as_str()),
        ("Trust Service type", qualification.service_type.as_str()),
        (
            "Trust Service status at timestamp",
            qualification.service_status.as_str(),
        ),
        (
            "current Trust Service status",
            qualification.current_service_status.as_str(),
        ),
        (
            "Trust Service identifier",
            qualification.service_identifier.as_str(),
        ),
        (
            "qualification type",
            qualification.qualification_type.as_str(),
        ),
        (
            "timestamp-time qualification status valid from",
            qualification.status_valid_from.as_str(),
        ),
        (
            "timestamp-time qualification status valid until",
            qualification.status_valid_until.as_str(),
        ),
        (
            "current qualification status valid from",
            qualification.current_status_valid_from.as_str(),
        ),
        (
            "current qualification status valid until",
            qualification.current_status_valid_until.as_str(),
        ),
    ] {
        validate_win_ansi(label, value)?;
    }

    if let Some(trusted_list) = qualification.trusted_list.as_ref() {
        for (label, value) in [
            ("Trusted List source", trusted_list.source.as_str()),
            ("Trusted List territory", trusted_list.territory.as_str()),
            ("Trusted List version", trusted_list.version.as_str()),
            (
                "Trusted List sequence number",
                trusted_list.sequence_number.as_str(),
            ),
            (
                "Trusted List issue timestamp",
                trusted_list.issued_at.as_str(),
            ),
            (
                "Trusted List next update",
                trusted_list.next_update.as_str(),
            ),
            (
                "Trusted List validation timestamp",
                trusted_list.validated_at.as_str(),
            ),
        ] {
            validate_win_ansi(label, value)?;
        }
        if !trusted_list.sha256.trim().is_empty() {
            validate_sha256("Trusted List", &trusted_list.sha256)?;
        }
        if trusted_list.validation_status == TrustedListValidationStatus::Verified
            && (trusted_list.source.trim().is_empty()
                || trusted_list.sha256.trim().is_empty()
                || trusted_list.validated_at.trim().is_empty())
        {
            return Err(AppError::Data(
                "Certificate PDF cannot report a verified Trusted List without its source, SHA-256, and validation timestamp."
                    .into(),
            ));
        }
    }

    if !matches!(
        qualification.provider_identity_status,
        TimestampQualificationStatus::NotChecked
            | TimestampQualificationStatus::NotDocumented
            | TimestampQualificationStatus::NotVerified
            | TimestampQualificationStatus::ProviderIdentityVerified
            | TimestampQualificationStatus::CheckFailed
    ) {
        return Err(AppError::Data(
            "Certificate PDF contains an invalid provider-identity qualification state.".into(),
        ));
    }
    if !matches!(
        qualification.trust_service_status,
        TimestampQualificationStatus::NotChecked
            | TimestampQualificationStatus::NotDocumented
            | TimestampQualificationStatus::NotVerified
            | TimestampQualificationStatus::TrustServiceVerified
            | TimestampQualificationStatus::CheckFailed
    ) {
        return Err(AppError::Data(
            "Certificate PDF contains an invalid Trust Service qualification state.".into(),
        ));
    }
    for status in [
        qualification.eidas_qualification_status,
        qualification.current_qualification_status,
        qualification.qualification_at_timestamp,
    ] {
        if !matches!(
            status,
            TimestampQualificationStatus::NotChecked
                | TimestampQualificationStatus::NotDocumented
                | TimestampQualificationStatus::NotVerified
                | TimestampQualificationStatus::QualifiedServiceVerified
                | TimestampQualificationStatus::CheckFailed
        ) {
            return Err(AppError::Data(
                "Certificate PDF contains an invalid regulatory qualification state.".into(),
            ));
        }
    }
    if qualification.status == TimestampQualificationStatus::ProviderIdentityVerified
        && qualification.provider_identity_status
            != TimestampQualificationStatus::ProviderIdentityVerified
    {
        return Err(AppError::Data(
            "Certificate PDF contains an inconsistent verified provider identity state.".into(),
        ));
    }
    if qualification.status == TimestampQualificationStatus::TrustServiceVerified
        && qualification.trust_service_status != TimestampQualificationStatus::TrustServiceVerified
    {
        return Err(AppError::Data(
            "Certificate PDF contains an inconsistent verified Trust Service state.".into(),
        ));
    }

    let at_timestamp_qualified = qualification.status
        == TimestampQualificationStatus::QualifiedServiceVerified
        || qualification.eidas_qualification_status
            == TimestampQualificationStatus::QualifiedServiceVerified
        || qualification.qualification_at_timestamp
            == TimestampQualificationStatus::QualifiedServiceVerified;
    if at_timestamp_qualified
        && !(qualification.status == TimestampQualificationStatus::QualifiedServiceVerified
            && qualification.eidas_qualification_status
                == TimestampQualificationStatus::QualifiedServiceVerified
            && qualification.qualification_at_timestamp
                == TimestampQualificationStatus::QualifiedServiceVerified)
    {
        return Err(AppError::Data(
            "Certificate PDF contains inconsistent qualified-service status for the timestamp time."
                .into(),
        ));
    }
    let identity_verified = qualification.provider_identity_status
        == TimestampQualificationStatus::ProviderIdentityVerified;
    if identity_verified
        && (metadata.provider_identity_verified != Some(true)
            || metadata.certificate_sha256.trim().is_empty()
            || identity.certificate_sha256.trim().is_empty()
            || !metadata
                .certificate_sha256
                .eq_ignore_ascii_case(&identity.certificate_sha256))
    {
        return Err(AppError::Data(
            "Certificate PDF cannot report a verified provider identity without the matching cryptographically verified signer certificate."
                .into(),
        ));
    }
    let currently_qualified = qualification.current_qualification_status
        == TimestampQualificationStatus::QualifiedServiceVerified;
    let trust_service_verified =
        qualification.trust_service_status == TimestampQualificationStatus::TrustServiceVerified;
    if at_timestamp_qualified || currently_qualified || trust_service_verified {
        let trusted_list = qualification.trusted_list.as_ref().ok_or_else(|| {
            AppError::Data(
                "Certificate PDF cannot report a verified Trust Service without Trusted List evidence."
                    .into(),
            )
        })?;
        if trusted_list.validation_status != TrustedListValidationStatus::Verified {
            return Err(AppError::Data(
                "Certificate PDF cannot report a verified Trust Service from an unverified Trusted List."
                    .into(),
            ));
        }
        if qualification.provider_identity_status
            != TimestampQualificationStatus::ProviderIdentityVerified
            || identity.certificate_sha256.trim().is_empty()
        {
            return Err(AppError::Data(
                "Certificate PDF cannot report a verified Trust Service without a cryptographically verified signer identity."
                    .into(),
            ));
        }
        if qualification.checked_at.trim().is_empty()
            || qualification.trust_service_provider.trim().is_empty()
            || qualification.trust_service_name.trim().is_empty()
            || qualification.service_type.trim().is_empty()
        {
            return Err(AppError::Data(
                "Certificate PDF cannot report a verified Trust Service without its check time and matched service identity."
                    .into(),
            ));
        }
    }
    if at_timestamp_qualified || currently_qualified {
        if qualification.service_type != QUALIFIED_TIMESTAMP_SERVICE_TYPE_URI
            || qualification.qualification_type != QUALIFIED_TIMESTAMP_SERVICE_TYPE_URI
        {
            return Err(AppError::Data(
                "Certificate PDF qualified-service status does not identify the official qualified electronic time-stamp service type."
                    .into(),
            ));
        }
    }
    if at_timestamp_qualified
        && (qualification.service_status != QUALIFIED_SERVICE_GRANTED_STATUS_URI
            || qualification.status_valid_from.trim().is_empty())
    {
        return Err(AppError::Data(
            "Certificate PDF qualified-service status for the timestamp time is not backed by the official granted status URI and its status period."
                .into(),
        ));
    }
    if currently_qualified
        && (qualification.current_service_status != QUALIFIED_SERVICE_GRANTED_STATUS_URI
            || qualification.current_status_valid_from.trim().is_empty())
    {
        return Err(AppError::Data(
            "Certificate PDF current qualified-service status is not backed by the official granted status URI and its current status period."
                .into(),
        ));
    }
    Ok(())
}

fn external_timestamp_rows(snapshot: &ExternalTimestampPdfSnapshot<'_>) -> Vec<TableRow> {
    let mut rows = vec![TableRow::mono(
        "Original Certificate ID [System value]",
        snapshot.certificate_id,
    )];

    if let Some(metadata) = snapshot.provider_metadata {
        let open_timestamps = is_open_timestamps_metadata(metadata);
        rows.push(TableRow::plain(
            "Record source [System verification]",
            "Automatic provider response",
        ));
        push_documented_row(
            &mut rows,
            "Provider / issuer [Provider-derived metadata]",
            snapshot.provider,
            false,
        );
        push_documented_row(
            &mut rows,
            "Timestamp type [Provider-derived metadata]",
            snapshot.timestamp_type,
            false,
        );
        if open_timestamps && snapshot.timestamp_value.trim().is_empty() {
            rows.push(TableRow::plain(
                "Confirmed timestamp [System verification]",
                "PENDING — OpenTimestamps proof verification / upgrade required",
            ));
        } else {
            push_documented_row(
                &mut rows,
                "Timestamp value [Provider-derived metadata]",
                snapshot.timestamp_value,
                true,
            );
        }
        push_documented_row(
            &mut rows,
            "Referenced artifact [System value]",
            snapshot.referenced_artifact,
            false,
        );
        rows.push(TableRow::mono(
            "Referenced artifact path [System value]",
            documented(snapshot.referenced_artifact_path),
        ));
        rows.push(TableRow::mono(
            "Requested SHA-256 [System verification]",
            snapshot.referenced_sha256,
        ));
        rows.push(TableRow::mono(
            "Actual artifact SHA-256 [System verification]",
            snapshot.actual_sha256,
        ));
        rows.push(TableRow::system_plain(
            "Referenced hash match [System verification]",
            yes_no(snapshot.referenced_hash_match),
        ));
        push_documented_row(
            &mut rows,
            "Timestamp evidence filename [Evidence-derived metadata]",
            snapshot.evidence_file_name,
            false,
        );
        rows.push(TableRow::mono(
            "Timestamp evidence SHA-256 [System verification]",
            snapshot.evidence_sha256,
        ));
        push_documented_row(
            &mut rows,
            "Provider external reference ID [Provider-derived metadata]",
            snapshot.external_reference_id,
            true,
        );
        push_documented_row(
            &mut rows,
            if open_timestamps {
                "Calendar endpoint [Provider-derived metadata]"
            } else {
                "Provider verification URL [Provider-derived metadata]"
            },
            snapshot.provider_verification_url,
            true,
        );
        push_documented_row(
            &mut rows,
            "Provider response note [Provider-derived metadata]",
            snapshot.note,
            false,
        );
        provider_metadata_rows(&mut rows, metadata);
    } else {
        rows.push(TableRow::plain(
            "Record source [System value]",
            "Legacy manually recorded timestamp evidence",
        ));
        rows.push(TableRow::plain(
            "Provider verification result [System verification]",
            "ATTACHED – legacy manually recorded; no provider verification recorded",
        ));
        rows.push(TableRow::plain(
            "Provider / issuer [Legacy user-recorded fact]",
            documented(snapshot.provider),
        ));
        rows.push(TableRow::plain(
            "Timestamp type [Legacy user-recorded fact]",
            documented(snapshot.timestamp_type),
        ));
        rows.push(TableRow::mono(
            "Timestamp value [Legacy user-recorded fact]",
            documented(snapshot.timestamp_value),
        ));
        rows.push(TableRow::plain(
            "Referenced artifact [Legacy user-recorded fact]",
            documented(snapshot.referenced_artifact),
        ));
        rows.push(TableRow::mono(
            "Referenced artifact path [System value]",
            documented(snapshot.referenced_artifact_path),
        ));
        rows.push(TableRow::mono(
            "Referenced SHA-256 [Legacy user-recorded fact]",
            snapshot.referenced_sha256,
        ));
        rows.push(TableRow::mono(
            "Actual artifact SHA-256 [System verification]",
            snapshot.actual_sha256,
        ));
        rows.push(TableRow::system_plain(
            "Referenced hash match [System verification]",
            yes_no(snapshot.referenced_hash_match),
        ));
        rows.push(TableRow::plain(
            "Evidence filename [Evidence-derived metadata]",
            documented(snapshot.evidence_file_name),
        ));
        rows.push(TableRow::mono(
            "Timestamp evidence SHA-256 [System verification]",
            snapshot.evidence_sha256,
        ));
        rows.push(TableRow::mono(
            "External reference ID [Legacy user-recorded fact]",
            documented(snapshot.external_reference_id),
        ));
        rows.push(TableRow::mono(
            "Provider verification URL [Legacy user-recorded fact]",
            documented(snapshot.provider_verification_url),
        ));
        rows.push(TableRow::plain(
            "Note [Legacy user-recorded fact]",
            documented(snapshot.note),
        ));
    }

    rows.push(TableRow::mono(
        "Imported at [System value]",
        documented(snapshot.imported_at),
    ));
    rows.push(TableRow::plain(
        "Provenance [System value]",
        documented(snapshot.provenance),
    ));
    rows
}

fn push_documented_row(rows: &mut Vec<TableRow>, label: &str, value: &str, mono: bool) {
    if value.trim().is_empty() {
        return;
    }
    rows.push(if mono {
        TableRow::mono(label, value)
    } else {
        TableRow::plain(label, value)
    });
}

fn provider_metadata_rows(rows: &mut Vec<TableRow>, metadata: &TimestampProviderMetadata) {
    let open_timestamps = is_open_timestamps_metadata(metadata);
    let rfc3161 = metadata.protocol.contains("RFC 3161");
    let requested_policy = if metadata.requested_policy_oid.trim().is_empty() {
        "NONE (provider policy accepted)"
    } else {
        metadata.requested_policy_oid.as_str()
    };
    let trust_anchor_sha256 = metadata.trust_anchor_sha256.join(", ");
    for (label, value, mono) in [
        (
            "Timestamp adapter [Provider-derived metadata]",
            metadata.adapter.as_str(),
            false,
        ),
        (
            "Timestamp protocol [Provider-derived metadata]",
            metadata.protocol.as_str(),
            false,
        ),
        (
            "Request algorithm [Provider-derived metadata]",
            metadata.request_algorithm.as_str(),
            false,
        ),
        (
            "Provider response format [Provider-derived metadata]",
            metadata.response_format.as_str(),
            false,
        ),
        (
            if open_timestamps {
                "Calendar endpoint identifier [Provider-derived metadata]"
            } else {
                "Provider endpoint identifier [Provider-derived metadata]"
            },
            metadata.provider_endpoint_identifier.as_str(),
            false,
        ),
        (
            "Provider response archive [System value]",
            metadata.provider_response_file_name.as_str(),
            false,
        ),
        (
            "Provider response SHA-256 [System verification]",
            metadata.provider_response_sha256.as_str(),
            true,
        ),
        (
            "Finalization snapshot / revision ID [System verification]",
            metadata.referenced_revision_id.as_str(),
            true,
        ),
        (
            "Timestamp issuer [Provider-derived metadata]",
            metadata.issuer.as_str(),
            false,
        ),
        (
            "Timestamp certificate subject [Provider-derived metadata]",
            metadata.certificate_subject.as_str(),
            false,
        ),
        (
            "Timestamp certificate serial number [Provider-derived metadata]",
            metadata.certificate_serial_number.as_str(),
            true,
        ),
        (
            "Verification timestamp [System verification]",
            metadata.verification_timestamp.as_str(),
            true,
        ),
    ] {
        push_documented_row(rows, label, value, mono);
    }

    if rfc3161 {
        for (label, value, mono) in [
            (
                "Timestamp policy OID [Provider-derived metadata]",
                metadata.policy_oid.as_str(),
                false,
            ),
            (
                "RFC 3161 request nonce [System value]",
                metadata.request_nonce.as_str(),
                true,
            ),
            (
                "RFC 3161 response nonce [Provider-derived metadata]",
                metadata.response_nonce.as_str(),
                true,
            ),
            (
                "Requested timestamp policy OID [System value]",
                requested_policy,
                false,
            ),
            (
                "Cryptographic verifier [System verification]",
                metadata.cryptographic_verifier.as_str(),
                false,
            ),
            (
                "Trust-anchor SHA-256 [System verification]",
                trust_anchor_sha256.as_str(),
                true,
            ),
        ] {
            push_documented_row(rows, label, value, mono);
        }
    }

    rows.push(TableRow::system_plain(
        "Provider verification result [System verification]",
        provider_verification_status_label(metadata.verification_result),
    ));
    push_documented_row(
        rows,
        "Provider verification detail [System verification]",
        metadata.verification_message.as_str(),
        false,
    );
    if open_timestamps {
        rows.push(TableRow::system_plain(
            "OpenTimestamps proof verification [System verification]",
            "PENDING — upgrade/verification required",
        ));
        rows.push(TableRow::system_plain(
            "Local manifest / proof binding [System verification]",
            yes_no(metadata.provider_digest_match),
        ));
        rows.push(TableRow::system_plain(
            "CMS signature / trust chain [System verification]",
            "N/A — not RFC 3161",
        ));
    } else {
        for (label, value) in [
            (
                "Provider response structure valid [System verification]",
                metadata.response_structure_valid,
            ),
            (
                "Provider digest match [System verification]",
                metadata.provider_digest_match,
            ),
            (
                "RFC 3161 nonce match [System verification]",
                metadata.nonce_match,
            ),
            (
                "Requested policy match [System verification]",
                metadata.policy_match,
            ),
            (
                "Timestamp signature verified [System verification]",
                metadata.signature_verified,
            ),
            (
                "Timestamp trust chain verified [System verification]",
                metadata.trust_chain_verified,
            ),
        ] {
            if let Some(value) = value {
                rows.push(TableRow::system_plain(label, yes_no(Some(value))));
            }
        }
    }
}

fn external_timestamp_qualification_rows(
    snapshot: &ExternalTimestampPdfSnapshot<'_>,
) -> Vec<TableRow> {
    let mut rows = Vec::new();
    let Some(metadata) = snapshot.provider_metadata else {
        for (label, status) in [
            (
                "Provider identity [Independent trust verification]",
                TimestampQualificationStatus::NotDocumented,
            ),
            (
                "Trust Service [Independent trust verification]",
                TimestampQualificationStatus::NotDocumented,
            ),
            (
                "eIDAS qualification [Independent trust verification]",
                TimestampQualificationStatus::NotDocumented,
            ),
            (
                "Qualification at timestamp [Independent trust verification]",
                TimestampQualificationStatus::NotDocumented,
            ),
        ] {
            rows.push(TableRow::system_plain(
                label,
                qualification_status_label(status),
            ));
        }
        return rows;
    };
    let qualification = metadata.qualification.as_ref();
    let status =
        |field: fn(&crate::model::TimestampQualificationRecord) -> TimestampQualificationStatus| {
            qualification.map(field).unwrap_or_default()
        };
    for (label, value) in [
        (
            "Provider identity [Independent trust verification]",
            status(|value| value.provider_identity_status),
        ),
        (
            "Trust Service [Independent trust verification]",
            status(|value| value.trust_service_status),
        ),
        (
            "eIDAS qualification [Independent trust verification]",
            status(|value| value.eidas_qualification_status),
        ),
        (
            "Qualification at timestamp [Independent trust verification]",
            status(|value| value.qualification_at_timestamp),
        ),
        (
            "Current qualification [Independent trust verification]",
            status(|value| value.current_qualification_status),
        ),
    ] {
        rows.push(TableRow::system_plain(
            label,
            qualification_status_label(value),
        ));
    }
    let Some(qualification) = qualification else {
        rows.push(TableRow::plain(
            "Qualification detail [Independent trust verification]",
            "No validated qualification source was checked. This does not mean that the provider is unsafe or not qualified.",
        ));
        return rows;
    };
    if qualification.eidas_qualification_status
        == TimestampQualificationStatus::QualifiedServiceVerified
    {
        rows.push(TableRow::system_plain(
            "Verified higher qualification [Independent trust verification]",
            "eIDAS QUALIFIED TRUST SERVICE – VERIFIED",
        ));
    }
    for (label, value, mono) in [
        (
            "Qualification checked at [System verification]",
            qualification.checked_at.as_str(),
            true,
        ),
        (
            "Recognized Trust Service Provider [Independent trust verification]",
            qualification.trust_service_provider.as_str(),
            false,
        ),
        (
            "Recognized Trust Service [Independent trust verification]",
            qualification.trust_service_name.as_str(),
            false,
        ),
        (
            "Trust Service type [Independent trust verification]",
            qualification.service_type.as_str(),
            false,
        ),
        (
            "Service status at timestamp [Independent trust verification]",
            qualification.service_status.as_str(),
            false,
        ),
        (
            "Current service status [Independent trust verification]",
            qualification.current_service_status.as_str(),
            false,
        ),
        (
            "Trust Service identifier [Independent trust verification]",
            qualification.service_identifier.as_str(),
            true,
        ),
        (
            "Qualification type [Independent trust verification]",
            qualification.qualification_type.as_str(),
            false,
        ),
        (
            "Timestamp-time status valid from [Independent trust verification]",
            qualification.status_valid_from.as_str(),
            true,
        ),
        (
            "Timestamp-time status valid until [Independent trust verification]",
            qualification.status_valid_until.as_str(),
            true,
        ),
        (
            "Current status valid from [Independent trust verification]",
            qualification.current_status_valid_from.as_str(),
            true,
        ),
        (
            "Current status valid until [Independent trust verification]",
            qualification.current_status_valid_until.as_str(),
            true,
        ),
        (
            "Signer certificate SHA-256 [System verification]",
            qualification.identity.certificate_sha256.as_str(),
            true,
        ),
        (
            "Qualification detail [Independent trust verification]",
            qualification.message.as_str(),
            false,
        ),
    ] {
        push_documented_row(&mut rows, label, value, mono);
    }
    if let Some(source) = qualification.trusted_list.as_ref() {
        for (label, value, mono) in [
            (
                "Trusted List source [Independent trust verification]",
                source.source.as_str(),
                false,
            ),
            (
                "Trusted List territory [Independent trust verification]",
                source.territory.as_str(),
                false,
            ),
            (
                "Trusted List version / sequence [Independent trust verification]",
                if source.sequence_number.is_empty() {
                    source.version.as_str()
                } else {
                    source.sequence_number.as_str()
                },
                false,
            ),
            (
                "Trusted List issued at [Independent trust verification]",
                source.issued_at.as_str(),
                true,
            ),
            (
                "Trusted List next update [Independent trust verification]",
                source.next_update.as_str(),
                true,
            ),
            (
                "Trusted List SHA-256 [System verification]",
                source.sha256.as_str(),
                true,
            ),
            (
                "Trusted List validated at [System verification]",
                source.validated_at.as_str(),
                true,
            ),
        ] {
            push_documented_row(&mut rows, label, value, mono);
        }
        rows.push(TableRow::system_plain(
            "Trusted List validation [System verification]",
            trusted_list_validation_status_label(source.validation_status),
        ));
    }
    rows
}

fn trusted_list_validation_status_label(status: TrustedListValidationStatus) -> &'static str {
    match status {
        TrustedListValidationStatus::NotChecked => "NOT CHECKED",
        TrustedListValidationStatus::Verified => "VERIFIED",
        TrustedListValidationStatus::Failed => "FAILED",
    }
}

fn provider_configuration_status_label(
    status: TimestampProviderConfigurationStatus,
) -> &'static str {
    match status {
        TimestampProviderConfigurationStatus::Disabled => "DISABLED",
        TimestampProviderConfigurationStatus::NotConfigured => "NOT CONFIGURED",
        TimestampProviderConfigurationStatus::Ready => "READY",
        TimestampProviderConfigurationStatus::AuthenticationRequired => "AUTHENTICATION REQUIRED",
        TimestampProviderConfigurationStatus::AuthenticationFailed => "AUTHENTICATION FAILED",
        TimestampProviderConfigurationStatus::ConnectionFailed => "CONNECTION FAILED",
        TimestampProviderConfigurationStatus::VerificationConfigurationIncomplete => {
            "VERIFICATION CONFIGURATION INCOMPLETE"
        }
        TimestampProviderConfigurationStatus::ProviderError => "PROVIDER ERROR",
    }
}

fn qualification_status_label(status: TimestampQualificationStatus) -> &'static str {
    match status {
        TimestampQualificationStatus::NotChecked => "NOT CHECKED",
        TimestampQualificationStatus::NotDocumented => "NOT DOCUMENTED",
        TimestampQualificationStatus::NotVerified => "NOT VERIFIED",
        TimestampQualificationStatus::ProviderIdentityVerified => "PROVIDER IDENTITY VERIFIED",
        TimestampQualificationStatus::TrustServiceVerified => "TRUST SERVICE VERIFIED",
        TimestampQualificationStatus::QualifiedServiceVerified => "QUALIFIED SERVICE VERIFIED",
        TimestampQualificationStatus::CheckFailed => "CHECK FAILED",
    }
}

fn is_open_timestamps_metadata(metadata: &TimestampProviderMetadata) -> bool {
    metadata.adapter.eq_ignore_ascii_case("open_timestamps")
        || metadata
            .protocol
            .to_ascii_lowercase()
            .contains("opentimestamps")
}

fn provider_verification_status_label(status: ExternalTimestampStatus) -> &'static str {
    match status {
        ExternalTimestampStatus::NotRecorded => "NOT RECORDED",
        ExternalTimestampStatus::Requesting => "REQUESTING",
        ExternalTimestampStatus::Attached => "ATTACHED",
        ExternalTimestampStatus::Verified => "VERIFIED",
        ExternalTimestampStatus::VerificationFailed => "VERIFICATION FAILED",
        ExternalTimestampStatus::ProviderUnavailable => "PROVIDER UNAVAILABLE",
        ExternalTimestampStatus::AuthenticationFailed => "AUTHENTICATION FAILED",
        ExternalTimestampStatus::AnchorMismatch => "ANCHOR MISMATCH",
        ExternalTimestampStatus::Disabled => "DISABLED",
        ExternalTimestampStatus::Ready => "READY",
        ExternalTimestampStatus::ConfigurationIncomplete => "CONFIGURATION INCOMPLETE",
        ExternalTimestampStatus::AuthenticationRequired => "AUTHENTICATION REQUIRED",
        ExternalTimestampStatus::ConnectionFailed => "CONNECTION FAILED",
        ExternalTimestampStatus::UnsupportedResponse => "UNSUPPORTED RESPONSE",
        ExternalTimestampStatus::VerificationConfigurationIncomplete => {
            "VERIFICATION CONFIGURATION INCOMPLETE"
        }
    }
}

/// Render an A4, multi-page technical certificate from a finalized snapshot.
pub fn generate_pdf(snapshot: &CertificatePdfSnapshot<'_>) -> Result<Vec<u8>> {
    let workflow_config = validate_snapshot(snapshot)?;
    let step_labels = workflow_config
        .steps
        .iter()
        .map(|step| (step.id.as_str(), step.name.as_str()))
        .collect::<HashMap<_, _>>();

    let view_model = CertificateViewModel::from_snapshot(snapshot);
    let mut layout = PdfLayout::new(snapshot.render_options);
    layout.set_running_header(&snapshot.track.fields.title, &snapshot.profile.artist_name);
    render_certificate_summary(&mut layout, &view_model);
    layout.new_page();
    render_evidence_overview(&mut layout, &view_model);
    layout.new_page();
    let toc_page = layout.current_page_index();
    layout.mark_bookmark("Contents", toc_page);
    layout.new_page();
    render_full_technical_intro(&mut layout);
    render_header_metadata(&mut layout, snapshot);
    render_track_data(&mut layout, snapshot);
    render_final_suno_generation(&mut layout, snapshot);
    render_sources_and_generation(&mut layout, snapshot);
    render_human_contribution(&mut layout, snapshot);
    render_suno_field(&mut layout, snapshot);
    render_ai_usage(&mut layout, snapshot);
    render_artwork_checks(&mut layout, snapshot);
    render_license_and_rights(&mut layout, snapshot);
    render_external_timestamp_base(&mut layout, snapshot);
    render_evidence_register(&mut layout, snapshot.evidence);
    render_integrity_anchors(&mut layout, snapshot);
    render_workflow(&mut layout, snapshot.steps, &step_labels);
    render_audio_screening(&mut layout, snapshot);
    render_certificate_statement(&mut layout, snapshot);
    render_technical_appendix(&mut layout, snapshot);
    layout.render_contents_page(toc_page);

    let (pages, bookmarks) = layout.into_pages(snapshot.certificate_id);
    let document_title = localized_certificate_label(snapshot.render_options, DOCUMENT_TITLE);
    let mut document = PdfDocument::new(&document_title);
    document.metadata.info.author = snapshot.profile.artist_name.clone();
    document.metadata.info.creator = GENERATED_BY.to_owned();
    document.metadata.info.producer = GENERATED_BY.to_owned();
    document.metadata.info.subject = localized_certificate_paragraph(
        snapshot.render_options,
        "Finalized technical documentation, evidence, and integrity snapshot",
    );
    document.metadata.info.identifier = snapshot.certificate_id.to_owned();
    document.metadata.info.keywords = vec![
        "SunoDM".to_owned(),
        "documentation".to_owned(),
        "evidence".to_owned(),
        "SHA-256".to_owned(),
    ];
    install_artwork_xobjects(&mut document, snapshot.artwork_previews);
    if bookmarks
        .iter()
        .any(|bookmark| bookmark.page_index >= pages.len())
    {
        return Err(AppError::Validation(
            "Certificate PDF bookmark target is outside the document.".into(),
        ));
    }
    for (index, bookmark) in bookmarks.iter().enumerate() {
        document.bookmarks.map.insert(
            PageAnnotId(format!("SunoDMBookmark{index:03}")),
            printpdf::PageAnnotation {
                name: bookmark.title.clone(),
                // printpdf serializes bookmark destinations as 1-based page
                // numbers and subtracts one internally.
                page: bookmark.page_index + 1,
            },
        );
    }
    document.with_pages(pages);

    let language = match snapshot.render_options.language {
        CertificateLanguage::De => "de-DE",
        CertificateLanguage::En => "en-US",
    };
    serialize_pdfa_2b(
        document,
        snapshot.certificate_id,
        snapshot.finalized_at,
        language,
    )
}

fn install_artwork_xobjects(document: &mut PdfDocument, previews: &[CertificateArtworkPreview]) {
    let mut installed = HashSet::new();
    for preview in previews {
        if !installed.insert(preview.resource_id.as_str()) {
            continue;
        }
        let mut dictionary = BTreeMap::new();
        dictionary.insert("Type".into(), DictItem::Name(b"XObject".to_vec()));
        dictionary.insert("Subtype".into(), DictItem::Name(b"Image".to_vec()));
        dictionary.insert(
            "Width".into(),
            DictItem::Int(i64::from(preview.width_pixels)),
        );
        dictionary.insert(
            "Height".into(),
            DictItem::Int(i64::from(preview.height_pixels)),
        );
        dictionary.insert("ColorSpace".into(), DictItem::Name(b"DeviceCMYK".to_vec()));
        dictionary.insert("BitsPerComponent".into(), DictItem::Int(8));
        // PDF/A-2 requires image interpolation to be absent or explicitly
        // disabled.  Keep it explicit so the conformance validator can prove
        // the generated thumbnail resources are compliant.
        dictionary.insert("Interpolate".into(), DictItem::Bool(false));
        let xobject = ExternalXObject {
            stream: ExternalStream {
                dict: dictionary,
                content: preview.cmyk_pixels.as_ref().clone(),
                compress: true,
            },
            width: Some(Px(preview.width_pixels as usize)),
            height: Some(Px(preview.height_pixels as usize)),
            dpi: Some(300.0),
        };
        document
            .resources
            .xobjects
            .map
            .insert(preview.xobject_id(), XObject::External(xobject));
    }
}

fn serialize_pdfa_2b(
    mut document: PdfDocument,
    deterministic_seed: &str,
    created_at: &str,
    language: &str,
) -> Result<Vec<u8>> {
    // DE/EN certificates are distinct archival renditions of one snapshot and
    // therefore need distinct, deterministic XMP/trailer identifiers.
    let rendition_seed = format!("{deterministic_seed}:{language}");
    let (pdf_date, xmp_date) = deterministic_pdf_dates(created_at)?;
    document.metadata.info.creation_date = pdf_date;
    document.metadata.info.modification_date = pdf_date;
    document.metadata.info.metadata_date = pdf_date;
    document.metadata.info.conformance = PdfConformance::A2B_2011_PDF_1_7;
    install_archive_fonts(&mut document)?;

    let xmp = render_pdfa_xmp(
        &document.metadata.info,
        &rendition_seed,
        &xmp_date,
        language,
    );
    // The four project-owned archive assets are embedded in full. This keeps the
    // renderer independent of host fonts and preserves all glyphs needed for DE/EN.
    let save_options = PdfSaveOptions {
        subset_fonts: false,
        ..PdfSaveOptions::default()
    };
    let mut warnings = Vec::new();
    let mut archive = document.to_lopdf_document(&save_options, &mut warnings);
    if let Some(warning) = warnings
        .iter()
        .find(|warning| warning.severity == PdfParseErrorSeverity::Error)
    {
        return Err(AppError::Data(format!(
            "Certificate PDF serialization failed: {}",
            warning.msg
        )));
    }
    postprocess_pdfa_2b(&mut archive, &rendition_seed, language, xmp)?;

    let mut bytes = Vec::new();
    archive
        .save_to(&mut bytes)
        .map_err(|error| AppError::Data(format!("PDF/A-2b serialization failed: {error}")))?;
    validate_pdfa_2b_bytes(&bytes)?;
    Ok(bytes)
}

fn deterministic_pdf_dates(created_at: &str) -> Result<(printpdf::date::OffsetDateTime, String)> {
    let parsed = DateTime::parse_from_rfc3339(created_at)
        .map_err(|_| AppError::Data("Certificate PDF timestamp is not valid RFC 3339.".into()))?;
    let utc = parsed.with_timezone(&Utc);
    let pdf_date =
        printpdf::date::OffsetDateTime::from_unix_timestamp(utc.timestamp()).map_err(|error| {
            AppError::Data(format!("Certificate PDF timestamp is invalid: {error}"))
        })?;
    Ok((pdf_date, utc.to_rfc3339_opts(SecondsFormat::Secs, true)))
}

fn render_pdfa_xmp(
    info: &printpdf::PdfDocumentInfo,
    deterministic_seed: &str,
    date: &str,
    language: &str,
) -> String {
    let document_id = deterministic_uuid(deterministic_seed, "document");
    let instance_id = deterministic_uuid(deterministic_seed, "instance");
    let title = xml_escape(&info.document_title);
    let author = xml_escape(&info.author);
    let creator = xml_escape(&info.creator);
    let producer = xml_escape(&info.producer);
    let subject = xml_escape(&info.subject);
    let identifier = xml_escape(&info.identifier);
    let keywords = xml_escape(&info.keywords.join(","));
    let date = xml_escape(date);
    let language = xml_escape(language);

    format!(
        r#"<?xpacket begin="﻿" id="W5M0MpCehiHzreSzNTczkc9d"?>
<x:xmpmeta xmlns:x="adobe:ns:meta/" x:xmptk="{producer}">
  <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">
    <rdf:Description rdf:about=""
      xmlns:dc="http://purl.org/dc/elements/1.1/"
      xmlns:pdf="http://ns.adobe.com/pdf/1.3/"
      xmlns:pdfaid="http://www.aiim.org/pdfa/ns/id/"
      xmlns:xmp="http://ns.adobe.com/xap/1.0/"
      xmlns:xmpMM="http://ns.adobe.com/xap/1.0/mm/">
      <pdfaid:part>{PDFA_PART}</pdfaid:part>
      <pdfaid:conformance>{PDFA_CONFORMANCE}</pdfaid:conformance>
      <dc:format>application/pdf</dc:format>
      <dc:title><rdf:Alt><rdf:li xml:lang="x-default">{title}</rdf:li></rdf:Alt></dc:title>
      <dc:creator><rdf:Seq><rdf:li>{author}</rdf:li></rdf:Seq></dc:creator>
      <dc:description><rdf:Alt><rdf:li xml:lang="x-default">{subject}</rdf:li></rdf:Alt></dc:description>
      <dc:identifier>{identifier}</dc:identifier>
      <dc:language><rdf:Bag><rdf:li>{language}</rdf:li></rdf:Bag></dc:language>
      <xmp:CreateDate>{date}</xmp:CreateDate>
      <xmp:ModifyDate>{date}</xmp:ModifyDate>
      <xmp:MetadataDate>{date}</xmp:MetadataDate>
      <xmp:CreatorTool>{creator}</xmp:CreatorTool>
      <pdf:Producer>{producer}</pdf:Producer>
      <pdf:Keywords>{keywords}</pdf:Keywords>
      <xmpMM:DocumentID>uuid:{document_id}</xmpMM:DocumentID>
      <xmpMM:InstanceID>uuid:{instance_id}</xmpMM:InstanceID>
    </rdf:Description>
  </rdf:RDF>
</x:xmpmeta>
<?xpacket end="w"?>"#
    )
}

fn xml_escape(value: &str) -> String {
    value
        .chars()
        .map(|character| match character {
            '&' => "&amp;".to_owned(),
            '<' => "&lt;".to_owned(),
            '>' => "&gt;".to_owned(),
            '"' => "&quot;".to_owned(),
            '\'' => "&apos;".to_owned(),
            character => character.to_string(),
        })
        .collect()
}

fn deterministic_uuid(seed: &str, purpose: &str) -> String {
    let digest = crate::security::sha256_bytes(format!("{purpose}:{seed}").as_bytes());
    format!(
        "{}-{}-{}-{}-{}",
        &digest[0..8],
        &digest[8..12],
        &digest[12..16],
        &digest[16..20],
        &digest[20..32]
    )
}

fn postprocess_pdfa_2b(
    document: &mut LoDocument,
    deterministic_seed: &str,
    language: &str,
    xmp: String,
) -> Result<()> {
    document.version = "1.7".into();
    document.binary_mark = vec![0xe2, 0xe3, 0xcf, 0xd3];

    // `ExternalStream::compress` only marks the stream as compressible in
    // printpdf 0.12.5; its document conversion does not call `compress()`.
    // Compress derived thumbnails explicitly to keep certificate size bounded.
    for object in document.objects.values_mut() {
        let LoObject::Stream(stream) = object else {
            continue;
        };
        let is_image =
            stream.dict.get(b"Subtype").and_then(LoObject::as_name).ok() == Some(b"Image");
        let already_filtered = stream.dict.has(b"Filter");
        if is_image && !already_filtered {
            stream.compress().map_err(|error| {
                AppError::Data(format!("Artwork preview compression failed: {error}"))
            })?;
        }
    }

    let root_id = document
        .trailer
        .get(b"Root")
        .and_then(LoObject::as_reference)
        .map_err(|_| AppError::Data("PDF/A catalog reference is missing.".into()))?;
    let metadata = LoStream::new(
        LoDictionary::from_iter([
            ("Type", LoObject::Name(b"Metadata".to_vec())),
            ("Subtype", LoObject::Name(b"XML".to_vec())),
        ]),
        xmp.into_bytes(),
    );
    let metadata_id = document.add_object(LoObject::Stream(metadata));

    {
        let catalog = document
            .get_dictionary_mut(root_id)
            .map_err(|_| AppError::Data("PDF/A catalog is invalid.".into()))?;
        catalog.set("Metadata", LoObject::Reference(metadata_id));
        catalog.set(
            "Lang",
            LoObject::String(language.as_bytes().to_vec(), LoStringFormat::Literal),
        );
        let intents = catalog
            .get_mut(b"OutputIntents")
            .and_then(LoObject::as_array_mut)
            .map_err(|_| AppError::Data("PDF/A output intent is missing.".into()))?;
        let intent = intents
            .first_mut()
            .ok_or_else(|| AppError::Data("PDF/A output intent is empty.".into()))?
            .as_dict_mut()
            .map_err(|_| AppError::Data("PDF/A output intent is invalid.".into()))?;
        intent.set("S", LoObject::Name(b"GTS_PDFA1".to_vec()));
        if let Some(profile) = intent.remove(b"DestinationOutputProfile") {
            intent.set("DestOutputProfile", profile);
        }
        intent.remove(b"License");
    }
    name_archive_fonts(document)?;

    if let Ok(info_id) = document
        .trailer
        .get(b"Info")
        .and_then(LoObject::as_reference)
    {
        if let Ok(info) = document.get_dictionary_mut(info_id) {
            info.remove(b"GTS_PDFXVersion");
        }
    }

    let digest = crate::security::sha256_bytes(deterministic_seed.as_bytes());
    document.trailer.set(
        "ID",
        LoObject::Array(vec![
            LoObject::String(digest.as_bytes()[..32].to_vec(), LoStringFormat::Literal),
            LoObject::String(digest.as_bytes()[32..].to_vec(), LoStringFormat::Literal),
        ]),
    );
    Ok(())
}

fn name_archive_fonts(document: &mut LoDocument) -> Result<()> {
    let type_zero_ids = document
        .objects
        .iter()
        .filter_map(|(id, object)| {
            let dictionary = object.as_dict().ok()?;
            (dictionary.get(b"Subtype").and_then(LoObject::as_name).ok() == Some(b"Type0"))
                .then_some(*id)
        })
        .collect::<Vec<_>>();

    for font_id in type_zero_ids {
        let (descriptor_id, archive_name) = {
            let font = document
                .get_dictionary_mut(font_id)
                .map_err(|_| AppError::Data("PDF/A Type0 font dictionary is invalid.".into()))?;
            let base_font = font
                .get(b"BaseFont")
                .and_then(LoObject::as_name)
                .map_err(|_| AppError::Data("PDF/A font has no BaseFont name.".into()))?;
            let archive_name = archive_font_name(base_font).ok_or_else(|| {
                AppError::Data(format!(
                    "Unexpected bundled PDF/A font {}.",
                    String::from_utf8_lossy(base_font)
                ))
            })?;
            let archive_name = archive_name.as_bytes().to_vec();
            font.set("BaseFont", LoObject::Name(archive_name.clone()));

            let descendants = font
                .get_mut(b"DescendantFonts")
                .and_then(LoObject::as_array_mut)
                .map_err(|_| AppError::Data("PDF/A descendant font list is invalid.".into()))?;
            let descendant = descendants
                .first_mut()
                .ok_or_else(|| AppError::Data("PDF/A descendant font list is empty.".into()))?
                .as_dict_mut()
                .map_err(|_| AppError::Data("PDF/A descendant font is invalid.".into()))?;
            descendant.set("BaseFont", LoObject::Name(archive_name.clone()));
            let descriptor_id = descendant
                .get(b"FontDescriptor")
                .and_then(LoObject::as_reference)
                .map_err(|_| {
                    AppError::Data("PDF/A font descriptor reference is invalid.".into())
                })?;
            (descriptor_id, archive_name)
        };

        let descriptor = document
            .get_dictionary_mut(descriptor_id)
            .map_err(|_| AppError::Data("PDF/A font descriptor is invalid.".into()))?;
        descriptor.set("FontName", LoObject::Name(archive_name));
    }
    Ok(())
}

fn archive_font_name(base_font: &[u8]) -> Option<&'static str> {
    match base_font {
        b"SANSRG" | b"DejaVuSans" => Some("DejaVuSans"),
        b"SANSBD" | b"DejaVuSans-Bold" => Some("DejaVuSans-Bold"),
        b"MONORG" | b"DejaVuSansMono" => Some("DejaVuSansMono"),
        b"MONOBD" | b"DejaVuSansMono-Bold" => Some("DejaVuSansMono-Bold"),
        _ => None,
    }
}

/// Parse staged PDF bytes and reject malformed documents. Current PDF/A documents receive the
/// stricter archive-profile checks while historical non-PDF/A certificates remain readable.
pub fn validate_pdf_bytes(bytes: &[u8]) -> Result<()> {
    validate_parseable_pdf(bytes)?;
    if pdf_claims_pdfa(bytes)? {
        validate_pdfa_2b_bytes(bytes)?;
    }
    Ok(())
}

fn validate_parseable_pdf(bytes: &[u8]) -> Result<()> {
    if !bytes.starts_with(b"%PDF-") {
        return Err(AppError::Validation(
            "Generated certificate PDF has no valid PDF header.".into(),
        ));
    }

    let mut warnings = Vec::new();
    let document =
        PdfDocument::parse(bytes, &PdfParseOptions::default(), &mut warnings).map_err(|error| {
            AppError::Validation(format!(
                "Generated certificate PDF cannot be parsed: {error}"
            ))
        })?;
    if document.pages.is_empty() {
        return Err(AppError::Validation(
            "Generated certificate PDF contains no pages.".into(),
        ));
    }
    if let Some(warning) = warnings
        .iter()
        .find(|warning| warning.severity == PdfParseErrorSeverity::Error)
    {
        return Err(AppError::Validation(format!(
            "Generated certificate PDF contains an invalid operation: {}",
            warning.msg
        )));
    }
    Ok(())
}

fn pdf_claims_pdfa(bytes: &[u8]) -> Result<bool> {
    let document = LoDocument::load_mem_with_options(
        bytes,
        LoLoadOptions::with_max_decompressed_size(PDF_STREAM_MAX_DECOMPRESSED_BYTES),
    )
    .map_err(|error| AppError::Validation(format!("PDF structure is invalid: {error}")))?;
    let metadata = pdf_metadata_bytes(&document)?;
    Ok(metadata.as_deref().is_some_and(|value| {
        value
            .windows(b"pdfaid:part".len())
            .any(|part| part == b"pdfaid:part")
    }))
}

pub fn validate_pdfa_2b_bytes(bytes: &[u8]) -> Result<()> {
    let archive_metadata = certificate_pdf_archive_metadata();
    if archive_metadata.archive_format != "PDF/A-2b" || archive_metadata.font_embedding != "full" {
        return Err(AppError::Validation(
            "Certificate PDF archive metadata configuration is invalid.".into(),
        ));
    }
    let document = LoDocument::load_mem_with_options(
        bytes,
        LoLoadOptions::with_max_decompressed_size(PDF_STREAM_MAX_DECOMPRESSED_BYTES),
    )
    .map_err(|error| AppError::Validation(format!("PDF/A structure is invalid: {error}")))?;
    if document.version != "1.7" {
        return Err(AppError::Validation(
            "Certificate PDF/A document must use PDF 1.7.".into(),
        ));
    }
    if document.trailer.has(b"Encrypt") || document.encryption_state.is_some() {
        return Err(AppError::Validation(
            "Certificate PDF/A document must not be encrypted.".into(),
        ));
    }
    if document.get_pages().is_empty() {
        return Err(AppError::Validation(
            "Certificate PDF/A document contains no pages.".into(),
        ));
    }

    validate_pdfa_xmp(&document)?;
    validate_pdfa_output_intent(&document, archive_metadata.output_intent)?;
    validate_a4_page_boxes(&document)?;
    validate_pdfa_page_colors(&document)?;
    validate_pdfa_image_xobjects(&document)?;
    validate_embedded_fonts(&document, archive_metadata.embedded_fonts)?;
    validate_deterministic_trailer_id(&document)?;
    Ok(())
}

fn validate_a4_page_boxes(document: &LoDocument) -> Result<()> {
    let expected = [
        0.0_f32,
        0.0_f32,
        PAGE_WIDTH_MM * 72.0 / 25.4,
        PAGE_HEIGHT_MM * 72.0 / 25.4,
    ];
    for page_id in document.get_pages().values() {
        let page = document
            .get_dictionary(*page_id)
            .map_err(|_| AppError::Validation("PDF/A page dictionary is invalid.".into()))?;
        if page
            .get(b"Rotate")
            .and_then(LoObject::as_i64)
            .is_ok_and(|rotation| rotation != 0)
        {
            return Err(AppError::Validation(
                "Certificate PDF pages must not be rotated.".into(),
            ));
        }
        for box_name in [b"MediaBox".as_slice(), b"CropBox", b"TrimBox"] {
            let values = page
                .get(box_name)
                .and_then(LoObject::as_array)
                .map_err(|_| {
                    AppError::Validation(format!(
                        "Certificate PDF page has no valid {}.",
                        String::from_utf8_lossy(box_name)
                    ))
                })?;
            if values.len() != expected.len()
                || values.iter().zip(expected).any(|(actual, expected)| {
                    actual
                        .as_float()
                        .map_or(true, |actual| (actual - expected).abs() > 0.02)
                })
            {
                return Err(AppError::Validation(format!(
                    "Certificate PDF {} is not A4.",
                    String::from_utf8_lossy(box_name)
                )));
            }
        }
    }
    Ok(())
}

fn pdf_metadata_bytes(document: &LoDocument) -> Result<Option<Vec<u8>>> {
    let root_id = document
        .trailer
        .get(b"Root")
        .and_then(LoObject::as_reference)
        .map_err(|_| AppError::Validation("PDF catalog reference is missing.".into()))?;
    let catalog = document
        .get_dictionary(root_id)
        .map_err(|_| AppError::Validation("PDF catalog is invalid.".into()))?;
    let Ok(metadata_id) = catalog.get(b"Metadata").and_then(LoObject::as_reference) else {
        return Ok(None);
    };
    let metadata = document
        .get_object(metadata_id)
        .and_then(LoObject::as_stream)
        .map_err(|_| AppError::Validation("PDF metadata stream is invalid.".into()))?;
    if metadata.dict.get(b"Type").and_then(LoObject::as_name).ok() != Some(b"Metadata")
        || metadata
            .dict
            .get(b"Subtype")
            .and_then(LoObject::as_name)
            .ok()
            != Some(b"XML")
    {
        return Err(AppError::Validation(
            "PDF metadata stream is not declared as XML metadata.".into(),
        ));
    }
    metadata
        .decompressed_content()
        .map(Some)
        .map_err(|_| AppError::Validation("PDF metadata stream cannot be decoded.".into()))
}

fn validate_pdfa_xmp(document: &LoDocument) -> Result<()> {
    let metadata = pdf_metadata_bytes(document)?.ok_or_else(|| {
        AppError::Validation("Certificate PDF/A document has no XMP metadata.".into())
    })?;
    let xmp = std::str::from_utf8(&metadata)
        .map_err(|_| AppError::Validation("Certificate PDF/A XMP is not UTF-8.".into()))?;
    for required in [
        "<pdfaid:part>2</pdfaid:part>",
        "<pdfaid:conformance>B</pdfaid:conformance>",
        "<dc:format>application/pdf</dc:format>",
        "<xmp:CreateDate>",
        "<xmpMM:DocumentID>uuid:",
        "<xmpMM:InstanceID>uuid:",
    ] {
        if !xmp.contains(required) {
            return Err(AppError::Validation(format!(
                "Certificate PDF/A XMP is missing {required}."
            )));
        }
    }
    Ok(())
}

fn validate_pdfa_output_intent(document: &LoDocument, expected_name: &str) -> Result<()> {
    let root_id = document
        .trailer
        .get(b"Root")
        .and_then(LoObject::as_reference)
        .map_err(|_| AppError::Validation("PDF/A catalog reference is missing.".into()))?;
    let catalog = document
        .get_dictionary(root_id)
        .map_err(|_| AppError::Validation("PDF/A catalog is invalid.".into()))?;
    let intents = catalog
        .get(b"OutputIntents")
        .and_then(LoObject::as_array)
        .map_err(|_| AppError::Validation("PDF/A output intent is missing.".into()))?;
    for item in intents {
        let resolved = resolve_object(document, item)?;
        let Ok(intent) = resolved.as_dict() else {
            continue;
        };
        if intent.get(b"S").and_then(LoObject::as_name).ok() != Some(b"GTS_PDFA1") {
            continue;
        }
        if intent.get(b"Info").and_then(LoObject::as_str).ok() != Some(expected_name.as_bytes()) {
            return Err(AppError::Validation(
                "PDF/A output intent identifier is unexpected.".into(),
            ));
        }
        let profile = intent
            .get(b"DestOutputProfile")
            .map_err(|_| AppError::Validation("PDF/A ICC profile reference is missing.".into()))?;
        let profile = resolve_object(document, profile)?;
        let profile = profile
            .as_stream()
            .map_err(|_| AppError::Validation("PDF/A ICC profile is invalid.".into()))?;
        let bytes = profile
            .decompressed_content()
            .map_err(|_| AppError::Validation("PDF/A ICC profile cannot be decoded.".into()))?;
        if profile.dict.get(b"N").and_then(LoObject::as_i64).ok() != Some(4)
            || bytes.len() < 128
            || bytes.get(8).is_none_or(|major_version| *major_version >= 5)
            || bytes.get(12..16) != Some(b"prtr")
            || bytes.get(16..20) != Some(b"CMYK")
            || bytes.get(36..40) != Some(b"acsp")
        {
            return Err(AppError::Validation(
                "PDF/A output intent does not contain a valid CMYK ICC profile.".into(),
            ));
        }
        return Ok(());
    }
    Err(AppError::Validation(
        "Certificate PDF/A document has no GTS_PDFA1 output intent.".into(),
    ))
}

fn validate_pdfa_page_colors(document: &LoDocument) -> Result<()> {
    for page_id in document.get_pages().values() {
        let content = document
            .get_page_content_with_limit(*page_id, PDF_PAGE_CONTENT_MAX_DECOMPRESSED_BYTES)
            .map_err(|_| {
                AppError::Validation("PDF/A page content exceeds the validation limit.".into())
            })?;
        let content = LoContent::decode(&content)
            .map_err(|_| AppError::Validation("PDF/A page operators are invalid.".into()))?;
        if content
            .operations
            .iter()
            .any(|operation| matches!(operation.operator.as_str(), "rg" | "RG"))
        {
            return Err(AppError::Validation(
                "PDF/A page uses DeviceRGB with a CMYK output intent.".into(),
            ));
        }
    }
    Ok(())
}

fn validate_pdfa_image_xobjects(document: &LoDocument) -> Result<()> {
    for object in document.objects.values() {
        let LoObject::Stream(stream) = object else {
            continue;
        };
        if stream.dict.get(b"Subtype").and_then(LoObject::as_name).ok() != Some(b"Image") {
            continue;
        }
        let width = stream
            .dict
            .get(b"Width")
            .and_then(LoObject::as_i64)
            .map_err(|_| AppError::Validation("PDF artwork image width is missing.".into()))?;
        let height = stream
            .dict
            .get(b"Height")
            .and_then(LoObject::as_i64)
            .map_err(|_| AppError::Validation("PDF artwork image height is missing.".into()))?;
        let interpolation_is_pdfa_safe = match stream.dict.get(b"Interpolate") {
            Err(_) | Ok(LoObject::Boolean(false)) => true,
            Ok(_) => false,
        };
        if width <= 0
            || height <= 0
            || width > i64::from(ARTWORK_PREVIEW_MAX_PIXELS)
            || height > i64::from(ARTWORK_PREVIEW_MAX_PIXELS)
            || stream
                .dict
                .get(b"BitsPerComponent")
                .and_then(LoObject::as_i64)
                .ok()
                != Some(8)
            || stream
                .dict
                .get(b"ColorSpace")
                .and_then(LoObject::as_name)
                .ok()
                != Some(b"DeviceCMYK")
            || stream.dict.has(b"SMask")
            || stream.dict.has(b"Mask")
            || stream.dict.has(b"Alternates")
            || stream.dict.has(b"OPI")
            || !interpolation_is_pdfa_safe
        {
            return Err(AppError::Validation(
                "PDF artwork image is not a bounded, opaque 8-bit CMYK preview.".into(),
            ));
        }
        let expected = usize::try_from(width)
            .ok()
            .and_then(|width| {
                usize::try_from(height)
                    .ok()
                    .and_then(|height| width.checked_mul(height))
            })
            .and_then(|pixels| pixels.checked_mul(4))
            .ok_or_else(|| AppError::Validation("PDF artwork image size overflow.".into()))?;
        let pixels = stream
            .decompressed_content_with_limit(expected.saturating_add(1))
            .map_err(|_| AppError::Validation("PDF artwork image cannot be decoded.".into()))?;
        if pixels.len() != expected {
            return Err(AppError::Validation(
                "PDF artwork image pixel length is inconsistent.".into(),
            ));
        }
    }
    Ok(())
}

fn validate_embedded_fonts(document: &LoDocument, expected_fonts: &[&str]) -> Result<()> {
    let mut embedded_fonts = HashSet::new();
    for page_id in document.get_pages().values() {
        let page = document
            .get_dictionary(*page_id)
            .map_err(|_| AppError::Validation("PDF/A page dictionary is invalid.".into()))?;
        let resources = page
            .get(b"Resources")
            .map_err(|_| AppError::Validation("PDF/A page resources are missing.".into()))?;
        let resources = resolve_object(document, resources)?;
        let resources = resources
            .as_dict()
            .map_err(|_| AppError::Validation("PDF/A page resources are invalid.".into()))?;
        let fonts = resources
            .get(b"Font")
            .map_err(|_| AppError::Validation("PDF/A page font resources are missing.".into()))?;
        let fonts = resolve_object(document, fonts)?;
        let fonts = fonts.as_dict().map_err(|_| {
            AppError::Validation("PDF/A font resource dictionary is invalid.".into())
        })?;
        for (resource_name, font) in fonts.iter() {
            let font_name = validate_embedded_font(document, resource_name, font)?;
            embedded_fonts.insert(font_name);
        }
    }
    if embedded_fonts.is_empty() {
        return Err(AppError::Validation(
            "Certificate PDF/A document contains no font resources.".into(),
        ));
    }
    let expected = expected_fonts
        .iter()
        .copied()
        .map(str::to_owned)
        .collect::<HashSet<_>>();
    if !embedded_fonts.is_subset(&expected) {
        return Err(AppError::Validation(
            "Certificate PDF/A embedded font set contains an unexpected font.".into(),
        ));
    }
    Ok(())
}

fn validate_embedded_font(
    document: &LoDocument,
    resource_name: &[u8],
    font: &LoObject,
) -> Result<String> {
    let font = resolve_object(document, font)?;
    let font = font
        .as_dict()
        .map_err(|_| AppError::Validation("PDF/A font dictionary is invalid.".into()))?;
    if font.get(b"Subtype").and_then(LoObject::as_name).ok() != Some(b"Type0") {
        return Err(AppError::Validation(format!(
            "PDF/A font {} is not an embedded composite font.",
            String::from_utf8_lossy(resource_name)
        )));
    }
    let base_font = font
        .get(b"BaseFont")
        .and_then(LoObject::as_name)
        .map_err(|_| AppError::Validation("PDF/A font has no BaseFont name.".into()))?;
    if base_font.contains(&b'+') {
        return Err(AppError::Validation(
            "PDF/A font metadata claims full embedding but uses a subset name.".into(),
        ));
    }
    let base_font_name = String::from_utf8(base_font.to_vec())
        .map_err(|_| AppError::Validation("PDF/A embedded font name is not ASCII.".into()))?;
    let to_unicode = font
        .get(b"ToUnicode")
        .map_err(|_| AppError::Validation("PDF/A embedded font has no ToUnicode map.".into()))?;
    let to_unicode = resolve_object(document, to_unicode)?;
    let to_unicode = to_unicode
        .as_stream()
        .map_err(|_| AppError::Validation("PDF/A ToUnicode map is invalid.".into()))?
        .decompressed_content()
        .map_err(|_| AppError::Validation("PDF/A ToUnicode map cannot be decoded.".into()))?;
    if to_unicode.is_empty() {
        return Err(AppError::Validation("PDF/A ToUnicode map is empty.".into()));
    }

    let descendants = font
        .get(b"DescendantFonts")
        .and_then(LoObject::as_array)
        .map_err(|_| AppError::Validation("PDF/A descendant font is missing.".into()))?;
    let descendant = descendants
        .first()
        .ok_or_else(|| AppError::Validation("PDF/A descendant font list is empty.".into()))?;
    let descendant = resolve_object(document, descendant)?;
    let descendant = descendant
        .as_dict()
        .map_err(|_| AppError::Validation("PDF/A descendant font is invalid.".into()))?;
    if descendant.get(b"BaseFont").and_then(LoObject::as_name).ok() != Some(base_font) {
        return Err(AppError::Validation(
            "PDF/A descendant font name does not match its Type0 font.".into(),
        ));
    }
    let descriptor = descendant
        .get(b"FontDescriptor")
        .map_err(|_| AppError::Validation("PDF/A font descriptor is missing.".into()))?;
    let descriptor = resolve_object(document, descriptor)?;
    let descriptor = descriptor
        .as_dict()
        .map_err(|_| AppError::Validation("PDF/A font descriptor is invalid.".into()))?;
    if descriptor.get(b"FontName").and_then(LoObject::as_name).ok() != Some(base_font) {
        return Err(AppError::Validation(
            "PDF/A font descriptor name does not match its Type0 font.".into(),
        ));
    }
    let font_file = descriptor
        .get(b"FontFile2")
        .or_else(|_| descriptor.get(b"FontFile3"))
        .map_err(|_| AppError::Validation("PDF/A font program is not embedded.".into()))?;
    let font_file = resolve_object(document, font_file)?;
    let font_file = font_file
        .as_stream()
        .map_err(|_| AppError::Validation("PDF/A embedded font program is invalid.".into()))?
        .decompressed_content()
        .map_err(|_| {
            AppError::Validation("PDF/A embedded font program cannot be decoded.".into())
        })?;
    if font_file.len() < 4 {
        return Err(AppError::Validation(
            "PDF/A embedded font program is empty.".into(),
        ));
    }
    validate_font_embedding_permissions(&font_file)?;
    Ok(base_font_name)
}

fn validate_font_embedding_permissions(font_file: &[u8]) -> Result<()> {
    let table_count = font_file
        .get(4..6)
        .and_then(|bytes| bytes.try_into().ok())
        .map(u16::from_be_bytes)
        .ok_or_else(|| AppError::Validation("PDF/A embedded font header is invalid.".into()))?;
    let mut os2_range = None;
    for index in 0..usize::from(table_count) {
        let record = 12 + index * 16;
        let Some(tag) = font_file.get(record..record + 4) else {
            break;
        };
        if tag != b"OS/2" {
            continue;
        }
        let offset = font_file
            .get(record + 8..record + 12)
            .and_then(|bytes| bytes.try_into().ok())
            .map(u32::from_be_bytes)
            .map(|value| value as usize)
            .ok_or_else(|| {
                AppError::Validation("PDF/A embedded font OS/2 offset is invalid.".into())
            })?;
        let length = font_file
            .get(record + 12..record + 16)
            .and_then(|bytes| bytes.try_into().ok())
            .map(u32::from_be_bytes)
            .map(|value| value as usize)
            .ok_or_else(|| {
                AppError::Validation("PDF/A embedded font OS/2 length is invalid.".into())
            })?;
        os2_range = offset.checked_add(length).map(|end| (offset, end));
        break;
    }
    let Some((offset, end)) = os2_range else {
        return Err(AppError::Validation(
            "PDF/A embedded TrueType font has no OS/2 permissions table.".into(),
        ));
    };
    let os2 = font_file
        .get(offset..end)
        .ok_or_else(|| AppError::Validation("PDF/A embedded font OS/2 table is invalid.".into()))?;
    let fs_type = os2
        .get(8..10)
        .and_then(|bytes| bytes.try_into().ok())
        .map(u16::from_be_bytes)
        .ok_or_else(|| {
            AppError::Validation("PDF/A embedded font permissions are invalid.".into())
        })?;
    if fs_type & 0x0002 != 0 || fs_type & 0x0100 != 0 {
        return Err(AppError::Validation(
            "PDF/A font license flags forbid embedding or subsetting.".into(),
        ));
    }
    Ok(())
}

fn validate_deterministic_trailer_id(document: &LoDocument) -> Result<()> {
    let ids = document
        .trailer
        .get(b"ID")
        .and_then(LoObject::as_array)
        .map_err(|_| AppError::Validation("PDF/A trailer ID is missing.".into()))?;
    if ids.len() != 2
        || ids
            .iter()
            .any(|id| id.as_str().map_or(true, |value| value.len() != 32))
    {
        return Err(AppError::Validation(
            "PDF/A trailer ID has an unexpected format.".into(),
        ));
    }
    Ok(())
}

fn resolve_object(document: &LoDocument, object: &LoObject) -> Result<LoObject> {
    match object {
        LoObject::Reference(id) => document
            .get_object(*id)
            .cloned()
            .map_err(|_| AppError::Validation("PDF indirect object is missing.".into())),
        object => Ok(object.clone()),
    }
}

fn validate_snapshot(snapshot: &CertificatePdfSnapshot<'_>) -> Result<workflow::WorkflowConfig> {
    for (label, value) in [
        ("certificate ID", snapshot.certificate_id),
        ("finalization timestamp", snapshot.finalized_at),
        ("certificate version", snapshot.certificate_version),
    ] {
        if value.trim().is_empty() {
            return Err(AppError::Data(format!(
                "Certificate PDF snapshot has no {label}."
            )));
        }
    }
    for (label, digest) in [
        ("SHA256SUMS.txt", snapshot.sha256sums_sha256),
        ("EVIDENCE_MANIFEST.json", snapshot.evidence_manifest_sha256),
        (
            "DOCUMENTATION_CERTIFICATE.md",
            snapshot.markdown_certificate_sha256,
        ),
    ] {
        validate_sha256(label, digest)?;
    }
    for (label, value) in [
        (
            "timestamp provider",
            snapshot.finalization_timestamp.provider.as_str(),
        ),
        (
            "timestamp provider configuration message",
            snapshot
                .finalization_timestamp
                .provider_configuration_message
                .as_str(),
        ),
        (
            "concrete timestamp message",
            snapshot.finalization_timestamp.technical_message.as_str(),
        ),
        (
            "timestamp value",
            snapshot.finalization_timestamp.timestamp_value.as_str(),
        ),
        (
            "timestamp external reference ID",
            snapshot
                .finalization_timestamp
                .external_reference_id
                .as_str(),
        ),
        (
            "timestamp provider endpoint",
            snapshot
                .finalization_timestamp
                .provider_verification_url
                .as_str(),
        ),
    ] {
        validate_win_ansi(label, value)?;
    }
    if let Some(metadata) = snapshot.finalization_timestamp.provider_metadata.as_ref() {
        validate_timestamp_qualification_metadata(metadata)?;
    }

    if snapshot
        .evidence
        .windows(2)
        .any(|items| items[0].relative_path > items[1].relative_path)
    {
        return Err(AppError::Data(
            "Certificate PDF evidence is not sorted by relative path.".into(),
        ));
    }
    for item in snapshot.evidence {
        if item.role == EvidenceRole::ExternalTimestamp {
            return Err(AppError::Data(
                "Phase-one certificate PDF cannot contain legacy external timestamp evidence."
                    .into(),
            ));
        }
        if !item.verified || item.verification_error.is_some() {
            return Err(AppError::Data(format!(
                "Certificate PDF evidence is not verified: {}",
                item.relative_path
            )));
        }
        let digest = item.sha256.as_deref().ok_or_else(|| {
            AppError::Data(format!(
                "Certificate PDF evidence has no SHA-256: {}",
                item.relative_path
            ))
        })?;
        validate_sha256(&item.relative_path, digest)?;
    }
    let mut preview_roles = HashSet::new();
    let mut preview_resources = HashMap::new();
    for preview in snapshot.artwork_previews {
        if !preview_roles.insert(preview.role)
            || preview.width_pixels == 0
            || preview.height_pixels == 0
            || preview.width_pixels > ARTWORK_PREVIEW_MAX_PIXELS
            || preview.height_pixels > ARTWORK_PREVIEW_MAX_PIXELS
            || preview.cmyk_pixels.len()
                != preview.width_pixels as usize * preview.height_pixels as usize * 4
        {
            return Err(AppError::Data(
                "Certificate PDF contains an invalid or duplicate artwork preview.".into(),
            ));
        }
        let resource_identity = (
            preview.sha256.as_str(),
            preview.width_pixels,
            preview.height_pixels,
        );
        if preview_resources
            .insert(preview.resource_id.as_str(), resource_identity)
            .is_some_and(|existing| existing != resource_identity)
        {
            return Err(AppError::Data(
                "Certificate PDF artwork resource ID is bound to different images.".into(),
            ));
        }
        let registered = snapshot.evidence.iter().copied().any(|item| {
            item.role == preview.role
                && item.id == preview.evidence_id
                && item.file_name == preview.file_name
                && item.relative_path == preview.relative_path
                && item
                    .sha256
                    .as_deref()
                    .is_some_and(|digest| digest.eq_ignore_ascii_case(&preview.sha256))
        });
        if !registered {
            return Err(AppError::Data(
                "Certificate PDF artwork preview is not bound to registered evidence.".into(),
            ));
        }
    }
    if snapshot.track.fields.suno_terms_evidence_not_available == Some(true)
        && snapshot
            .evidence
            .iter()
            .any(|item| item.role == EvidenceRole::SunoTermsRights)
    {
        return Err(AppError::Validation(
            "Certificate PDF cannot combine verified Terms evidence with an unavailable claim."
                .into(),
        ));
    }

    let config = workflow::config()?;
    if snapshot.track.workflow_id != config.id || snapshot.track.workflow_version != config.version
    {
        return Err(AppError::Data(
            "Certificate PDF workflow metadata does not match the configured workflow.".into(),
        ));
    }
    let configured_ids = config
        .steps
        .iter()
        .map(|step| step.id.as_str())
        .collect::<HashSet<_>>();
    let mut supplied_ids = HashSet::new();
    for step in snapshot.steps {
        if !configured_ids.contains(step.id.as_str()) {
            return Err(AppError::Data(format!(
                "Certificate PDF contains an unknown workflow step: {}",
                step.id
            )));
        }
        if !supplied_ids.insert(step.id.as_str()) {
            return Err(AppError::Data(format!(
                "Certificate PDF contains a duplicate workflow step: {}",
                step.id
            )));
        }
        match step.status {
            StepStatus::Pass => {}
            StepStatus::NotApplicable => {
                if step
                    .na_reason
                    .as_deref()
                    .is_none_or(|reason| reason.trim().is_empty())
                {
                    return Err(AppError::Data(format!(
                        "Certificate PDF workflow step has no N/A reason: {}",
                        step.id
                    )));
                }
            }
            _ => {
                return Err(AppError::Validation(format!(
                    "Certificate PDF workflow step is not complete: {} ({})",
                    step.id,
                    step_status(&step.status)
                )));
            }
        }
    }
    if supplied_ids.len() != configured_ids.len() {
        return Err(AppError::Data(
            "Certificate PDF workflow snapshot is incomplete.".into(),
        ));
    }
    if snapshot
        .deviations
        .iter()
        .any(|deviation| deviation.blocking && !deviation.resolved)
    {
        return Err(AppError::Validation(
            "Certificate PDF snapshot contains an open blocking deviation.".into(),
        ));
    }
    validate_audio_screening_consistency(&snapshot.track.audio_screening.external)?;
    validate_rendered_text(snapshot, &config)?;
    Ok(config)
}

fn validate_audio_screening_consistency(external: &AudioScreeningExternalRecord) -> Result<()> {
    if !external.track_coverage_percent.is_finite()
        || !(0.0..=100.0).contains(&external.track_coverage_percent)
    {
        return Err(AppError::Data(
            "Certificate PDF ACRCloud track coverage is outside the factual percentage range."
                .into(),
        ));
    }
    if let Some(source_duration) = external.source_duration_milliseconds {
        if source_duration == 0 && external.unique_sample_duration_milliseconds > 0 {
            return Err(AppError::Data(
                "Certificate PDF ACRCloud sampled duration has no positive source duration.".into(),
            ));
        }
        if source_duration > 0 {
            let expected = (external.unique_sample_duration_milliseconds as f64 * 100.0)
                / source_duration as f64;
            if format!("{:.2}", external.track_coverage_percent) != format!("{expected:.2}") {
                return Err(AppError::Data(
                    "Certificate PDF ACRCloud track coverage contradicts the documented durations."
                        .into(),
                ));
            }
        }
    }

    let mut sample_match_count = 0usize;
    for sample in &external.samples {
        let has_matches = !sample.matches.is_empty();
        match sample.status {
            AudioScreeningStatus::MatchDetected if !has_matches => {
                return Err(AppError::Data(format!(
                    "Certificate PDF ACRCloud sample {} reports MATCH DETECTED without a provider match record.",
                    sample.sequence
                )));
            }
            AudioScreeningStatus::MatchDetected => {
                sample_match_count += sample.matches.len();
            }
            _ if has_matches => {
                return Err(AppError::Data(format!(
                    "Certificate PDF ACRCloud sample {} contains provider matches but its result is not MATCH DETECTED.",
                    sample.sequence
                )));
            }
            _ => {}
        }
    }

    let has_any_match = sample_match_count > 0 || !external.matches.is_empty();
    match external.status {
        AudioScreeningStatus::MatchDetected if !has_any_match => {
            return Err(AppError::Data(
                "Certificate PDF ACRCloud overall result reports MATCH DETECTED without a provider match record."
                    .into(),
            ));
        }
        AudioScreeningStatus::MatchDetected => {}
        _ if has_any_match => {
            return Err(AppError::Data(
                "Certificate PDF ACRCloud overall result contradicts its provider match records."
                    .into(),
            ));
        }
        _ => {}
    }

    if sample_match_count > 0
        && !external.matches.is_empty()
        && !aggregate_matches_are_repeated_in_samples(external)
    {
        return Err(AppError::Data(
            "Certificate PDF ACRCloud aggregate matches contradict the per-sample records.".into(),
        ));
    }
    Ok(())
}

fn validate_sha256(label: &str, digest: &str) -> Result<()> {
    if digest.len() != 64 || !digest.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(AppError::Data(format!(
            "Certificate PDF has an invalid SHA-256 for {label}."
        )));
    }
    Ok(())
}

fn validate_rendered_text(
    snapshot: &CertificatePdfSnapshot<'_>,
    config: &workflow::WorkflowConfig,
) -> Result<()> {
    let fields = snapshot.track.fields.normalized_conditionals();
    for (label, value) in [
        ("track title", fields.title.as_str()),
        ("artist", snapshot.profile.artist_name.as_str()),
        ("Suno profile", snapshot.profile.suno_profile_name.as_str()),
        ("Suno handle", snapshot.profile.suno_handle.as_str()),
        (
            "Suno subscription start",
            snapshot.profile.subscription_start_date.as_str(),
        ),
        ("production start", fields.production_start_date.as_str()),
        ("production end", fields.production_end_date.as_str()),
        ("last editing date", fields.final_export_date.as_str()),
        ("Suno model", fields.suno_model.as_str()),
        ("Suno project URL", fields.suno_project_url.as_str()),
        (
            "Suno final generation ID",
            fields.suno_final_generation_id.as_str(),
        ),
        (
            "Suno final generation date",
            fields.suno_final_generation_date.as_str(),
        ),
        (
            "Suno download/export date",
            fields.suno_download_export_date.as_str(),
        ),
        (
            "Suno plan at generation",
            fields.suno_plan_at_generation.as_str(),
        ),
        (
            "legacy Suno plan-at-creation value",
            fields.legacy_suno_plan_at_creation.as_str(),
        ),
        (
            "Suno lyrics/structure field text",
            fields.suno_lyrics_field_text.as_str(),
        ),
        (
            "Suno other content type",
            fields.suno_lyrics_other_content_type.as_str(),
        ),
        (
            "unclassified legacy lyrics source",
            fields.lyrics_source.as_str(),
        ),
        (
            "unclassified legacy lyrics text",
            fields.lyrics_text.as_str(),
        ),
        ("Suno style prompt", fields.suno_style_prompt.as_str()),
        (
            "external audio source",
            fields.external_audio_source.as_str(),
        ),
        (
            "external audio provenance statement",
            fields.external_audio_ownership.as_str(),
        ),
        ("own audio source", fields.own_audio_source.as_str()),
        (
            "own audio provenance statement",
            fields.own_audio_ownership.as_str(),
        ),
        (
            "third-party sample source",
            fields.third_party_sample_source.as_str(),
        ),
        (
            "third-party sample provenance statement",
            fields.third_party_sample_ownership.as_str(),
        ),
        (
            "human editing details",
            fields.human_editing_details.as_str(),
        ),
        (
            "post-export editing details",
            fields.post_export_editing_details.as_str(),
        ),
        ("artwork origin", fields.artwork_origin.as_str()),
        ("AI image service", fields.ai_image_service.as_str()),
        (
            "code-audio post-processing note",
            fields.code_audio_post_processing_note.as_str(),
        ),
        (
            "human artwork process notes",
            fields.human_artwork_process_notes.as_str(),
        ),
        (
            "custom artwork change",
            fields.custom_artwork_change.as_str(),
        ),
        ("artwork disclosure text", fields.disclosure_text.as_str()),
        ("real-person note", fields.real_person_notes.as_str()),
        ("real-event note", fields.real_event_notes.as_str()),
        ("trademark/logo note", fields.trademark_notes.as_str()),
        ("audio AI system", fields.audio_ai_system.as_str()),
        (
            "audio disclosure text",
            fields.audio_disclosure_text.as_str(),
        ),
        (
            "audio disclosure reason",
            fields.audio_disclosure_reason.as_str(),
        ),
        ("release notes", fields.release_notes.as_str()),
        ("workflow ID", snapshot.track.workflow_id.as_str()),
        ("workflow version", snapshot.track.workflow_version.as_str()),
        ("certificate ID", snapshot.certificate_id),
        ("finalization timestamp", snapshot.finalized_at),
        ("certificate version", snapshot.certificate_version),
    ] {
        validate_win_ansi(label, value)?;
    }

    for (label, values) in [
        (
            "code-audio post-processing operation",
            fields.code_audio_post_processing_operations.as_slice(),
        ),
        (
            "human artwork process operation",
            fields.human_artwork_process_operations.as_slice(),
        ),
        (
            "human artwork modification",
            fields.human_artwork_modifications.as_slice(),
        ),
        (
            "audio disclosure location",
            fields.audio_disclosure_locations.as_slice(),
        ),
    ] {
        for value in values {
            validate_win_ansi(label, value)?;
        }
    }

    for step in snapshot.steps {
        if let Some(reason) = step.na_reason.as_deref() {
            validate_win_ansi("workflow N/A reason", reason)?;
        }
    }
    for step in &config.steps {
        validate_win_ansi("workflow step label", &step.name)?;
    }
    if let Some(suno_id) = snapshot.automation.suno_id.as_deref() {
        validate_win_ansi("evidence-derived Suno ID", suno_id)?;
    }
    for revision in snapshot.revision_references {
        validate_win_ansi("revision archive reference", revision)?;
    }
    for item in snapshot.evidence {
        validate_win_ansi("evidence ID", &item.id)?;
        validate_win_ansi("evidence file name", &item.file_name)?;
        validate_win_ansi("evidence relative path", &item.relative_path)?;
        validate_win_ansi("evidence imported timestamp", &item.imported_at)?;
        for (label, value) in [
            (
                "evidence original file name",
                item.metadata.original_file_name.as_str(),
            ),
            (
                "evidence document title",
                item.metadata.document_title.as_str(),
            ),
            ("evidence provider", item.metadata.provider.as_str()),
            ("evidence source URL", item.metadata.source_url.as_str()),
            (
                "evidence retrieval date",
                item.metadata.retrieval_date.as_str(),
            ),
            (
                "evidence effective date",
                item.metadata.effective_date.as_str(),
            ),
            (
                "evidence applicable production period",
                item.metadata.applicable_production_period.as_str(),
            ),
            ("evidence factual note", item.metadata.factual_note.as_str()),
            (
                "evidence file extension",
                item.metadata.file_extension.as_str(),
            ),
            ("evidence MIME type", item.metadata.mime_type.as_str()),
            ("evidence audio format", item.metadata.audio_format.as_str()),
            (
                "evidence Suno created timestamp",
                item.metadata.suno_created_timestamp.as_str(),
            ),
            (
                "evidence Suno created date",
                item.metadata.suno_created_date.as_str(),
            ),
            ("evidence Suno ID", item.metadata.suno_id.as_str()),
            (
                "evidence raw Suno metadata",
                item.metadata.suno_raw_metadata.as_str(),
            ),
        ] {
            validate_win_ansi(label, value)?;
        }
        for entry in &item.metadata.embedded_metadata {
            validate_win_ansi("embedded metadata key", &entry.key)?;
            validate_win_ansi("embedded metadata value", &entry.value)?;
        }
        for (label, value) in [
            ("evidence coverage start", item.coverage_start.as_deref()),
            ("evidence coverage end", item.coverage_end.as_deref()),
            (
                "source global evidence ID",
                item.source_global_evidence_id.as_deref(),
            ),
            (
                "derived evidence ID",
                item.derived_from_evidence_id.as_deref(),
            ),
            (
                "evidence generator version",
                item.generator_version.as_deref(),
            ),
            (
                "generated disclosure text",
                item.generated_disclosure_text.as_deref(),
            ),
        ] {
            if let Some(value) = value {
                validate_win_ansi(label, value)?;
            }
        }
    }

    let screening = &snapshot.track.audio_screening;
    for (label, value) in [
        ("local screening engine", screening.local.engine.as_str()),
        (
            "local screening engine version",
            screening.local.engine_version.as_str(),
        ),
        (
            "local fingerprint algorithm",
            screening.local.fingerprint_algorithm.as_str(),
        ),
        (
            "local screening source evidence ID",
            screening.local.source_evidence_id.as_str(),
        ),
        (
            "local screening source path",
            screening.local.source_relative_path.as_str(),
        ),
        (
            "local screening record path",
            screening.local.artifact_relative_path.as_str(),
        ),
        (
            "external screening provider",
            screening.external.provider.as_str(),
        ),
        (
            "external screening source evidence ID",
            screening.external.source_evidence_id.as_str(),
        ),
        (
            "external screening source path",
            screening.external.source_relative_path.as_str(),
        ),
    ] {
        validate_win_ansi(label, value)?;
    }
    for (label, value) in [
        (
            "external screening checked timestamp",
            screening.external.checked_at.as_deref(),
        ),
        (
            "external response archive path",
            screening.external.response_relative_path.as_deref(),
        ),
    ] {
        if let Some(value) = value {
            validate_win_ansi(label, value)?;
        }
    }
    for (index, item) in screening.external.matches.iter().enumerate() {
        validate_audio_screening_match_text(item, &format!("provider match {}", index + 1))?;
    }
    for sample in &screening.external.samples {
        for (label, value) in [
            (
                "provider status message",
                sample.provider_status_message.as_deref(),
            ),
            (
                "provider API version",
                sample.provider_api_version.as_deref(),
            ),
            (
                "sample response archive",
                sample.response_relative_path.as_deref(),
            ),
        ] {
            if let Some(value) = value {
                validate_win_ansi(label, value)?;
            }
        }
        for (index, item) in sample.matches.iter().enumerate() {
            validate_audio_screening_match_text(
                item,
                &format!("sample {} provider match {}", sample.sequence, index + 1),
            )?;
        }
    }
    Ok(())
}

fn validate_audio_screening_match_text(
    item: &crate::model::AudioScreeningMatch,
    context: &str,
) -> Result<()> {
    validate_win_ansi(&format!("{context} title"), &item.title)?;
    for artist in &item.artists {
        validate_win_ansi(&format!("{context} artist"), artist)?;
    }
    for (label, value) in [
        ("album", item.album.as_deref()),
        ("ISRC", item.isrc.as_deref()),
        ("ACRCloud ID", item.acrid.as_deref()),
    ] {
        if let Some(value) = value {
            validate_win_ansi(&format!("{context} {label}"), value)?;
        }
    }
    Ok(())
}

fn validate_win_ansi(label: &str, value: &str) -> Result<()> {
    if let Some(character) = value.chars().find(|character| !is_win_ansi(*character)) {
        return Err(AppError::Data(format!(
            "Certificate PDF {label} contains a character unsupported by the bundled archive fonts: U+{:04X}.",
            character as u32
        )));
    }
    Ok(())
}

fn is_win_ansi(character: char) -> bool {
    if matches!(character, '\n' | '\r' | '\t') {
        return true;
    }
    match character as u32 {
        0x20..=0x7e | 0xa0..=0xff => true,
        _ => matches!(
            character,
            '\u{20ac}'
                | '\u{201a}'
                | '\u{0192}'
                | '\u{201e}'
                | '\u{2026}'
                | '\u{2020}'
                | '\u{2021}'
                | '\u{02c6}'
                | '\u{2030}'
                | '\u{0160}'
                | '\u{2039}'
                | '\u{0152}'
                | '\u{017d}'
                | '\u{2018}'
                | '\u{2019}'
                | '\u{201c}'
                | '\u{201d}'
                | '\u{2022}'
                | '\u{2013}'
                | '\u{2014}'
                | '\u{02dc}'
                | '\u{2122}'
                | '\u{0161}'
                | '\u{203a}'
                | '\u{0153}'
                | '\u{017e}'
                | '\u{0178}'
        ),
    }
}

fn render_certificate_summary(layout: &mut PdfLayout, view: &CertificateViewModel<'_>) {
    let snapshot = view.snapshot;
    layout.mark_bookmark("Summary", layout.current_page_index());
    let document_title = layout.label(DOCUMENT_TITLE);
    layout.text_at(
        LEFT_MM,
        278.0,
        &document_title,
        fit_text_size(
            &document_title,
            RIGHT_MM - LEFT_MM,
            15.5,
            11.0,
            BuiltinFont::HelveticaBold,
        ),
        BuiltinFont::HelveticaBold,
    );
    let boundary =
        layout.paragraph("Technical evidence report — not a legal or governmental certification");
    layout.text_at(LEFT_MM, 269.5, &boundary, 7.2, BuiltinFont::Helvetica);
    layout.rule(LEFT_MM, RIGHT_MM, 265.0, 0.65);

    let title = documented(&snapshot.track.fields.title);
    for (index, line) in bounded_wrapped_lines(title, 112.0, 15.0, BuiltinFont::HelveticaBold, 2)
        .iter()
        .enumerate()
    {
        layout.text_at(
            LEFT_MM,
            252.0 - index as f32 * 6.5,
            line,
            15.0,
            BuiltinFont::HelveticaBold,
        );
    }
    for (index, line) in bounded_wrapped_lines(
        documented(&snapshot.profile.artist_name),
        112.0,
        9.5,
        BuiltinFont::Helvetica,
        2,
    )
    .iter()
    .enumerate()
    {
        layout.text_at(
            LEFT_MM,
            238.0 - index as f32 * 5.5,
            line,
            9.5,
            BuiltinFont::Helvetica,
        );
    }

    let metadata = [
        ("Certificate ID", snapshot.certificate_id, true),
        ("Finalization timestamp", snapshot.finalized_at, true),
        ("Application version", env!("CARGO_PKG_VERSION"), false),
        (
            "Workflow version",
            snapshot.track.workflow_version.as_str(),
            false,
        ),
        ("Certificate version", snapshot.certificate_version, false),
    ];
    let mut metadata_y = 224.0;
    for (label, value, mono) in metadata {
        let label = layout.label(label);
        layout.text_at(LEFT_MM, metadata_y, &label, 6.1, BuiltinFont::HelveticaBold);
        let font = if mono {
            BuiltinFont::Courier
        } else {
            BuiltinFont::Helvetica
        };
        let size = fit_text_size(value, 74.0, 6.8, 5.5, font);
        let displayed = ellipsize_text_to_width(value, 74.0, size, font);
        layout.text_at(LEFT_MM + 38.0, metadata_y, &displayed, size, font);
        metadata_y -= 7.0;
    }

    let artwork_x = 136.0;
    let artwork_top = 255.0;
    let artwork_size = 54.0;
    if let Some(preview) = view.final_artwork_preview {
        let (_, rendered_height) =
            layout.image_at(preview, artwork_x, artwork_top, artwork_size, artwork_size);
        let caption_y = artwork_top - rendered_height - 5.0;
        layout.text_at(
            artwork_x,
            caption_y,
            &layout.label("Final artwork preview"),
            6.1,
            BuiltinFont::HelveticaBold,
        );
        let caption_size = fit_text_size(
            &preview.file_name,
            artwork_size,
            5.8,
            5.5,
            BuiltinFont::Helvetica,
        );
        let caption = ellipsize_text_to_width(
            &preview.file_name,
            artwork_size,
            caption_size,
            BuiltinFont::Helvetica,
        );
        layout.text_at(
            artwork_x,
            caption_y - 5.0,
            &caption,
            caption_size,
            BuiltinFont::Helvetica,
        );
        layout.text_at(
            artwork_x,
            caption_y - 10.0,
            &format!("SHA-256 {}", abbreviated_sha256(&preview.sha256)),
            5.5,
            BuiltinFont::Courier,
        );
    } else {
        layout.box_outline(artwork_x, artwork_top, artwork_size, artwork_size, 0.4);
        let fallback = layout.paragraph("Artwork preview not available");
        let lines = wrap_text(
            &fallback,
            artwork_size - 8.0,
            7.0,
            BuiltinFont::HelveticaBold,
        );
        for (index, line) in lines.iter().enumerate() {
            layout.text_at(
                artwork_x + 4.0,
                artwork_top - 23.0 - index as f32 * 5.0,
                line,
                7.0,
                BuiltinFont::HelveticaBold,
            );
        }
        if let Some(item) = view.final_artwork {
            let caption_size = fit_text_size(
                &item.file_name,
                artwork_size,
                5.8,
                5.5,
                BuiltinFont::Helvetica,
            );
            let caption = ellipsize_text_to_width(
                &item.file_name,
                artwork_size,
                caption_size,
                BuiltinFont::Helvetica,
            );
            layout.text_at(
                artwork_x,
                artwork_top - artwork_size - 5.0,
                &caption,
                caption_size,
                BuiltinFont::Helvetica,
            );
            if let Some(digest) = item.sha256.as_deref() {
                layout.text_at(
                    artwork_x,
                    artwork_top - artwork_size - 10.0,
                    &format!("SHA-256 {}", abbreviated_sha256(digest)),
                    5.5,
                    BuiltinFont::Courier,
                );
            }
        }
    }

    layout.box_outline(LEFT_MM, 188.0, RIGHT_MM - LEFT_MM, 24.0, 0.65);
    layout.status_icon_at(LEFT_MM + 5.0, 177.8, StatusTone::Success);
    layout.status_text_at(
        LEFT_MM + 11.0,
        177.0,
        &format!("PASS  {}", layout.label("DOCUMENTATION COMPLETE")),
        12.0,
        BuiltinFont::HelveticaBold,
        StatusTone::Success,
    );
    layout.text_at(
        LEFT_MM + 5.0,
        169.5,
        &layout.paragraph("Configured documentation requirements completed"),
        7.0,
        BuiltinFont::Helvetica,
    );
    layout.text_at(
        139.0,
        169.5,
        &format!(
            "{}: {}",
            layout.label("Blocking deviations"),
            view.open_blocking_deviations
        ),
        7.0,
        BuiltinFont::HelveticaBold,
    );

    let positions = [
        (LEFT_MM, 157.0),
        (107.0, 157.0),
        (LEFT_MM, 118.0),
        (107.0, 118.0),
        (LEFT_MM, 79.0),
        (107.0, 79.0),
    ];
    for (group, (x_mm, top_mm)) in view.groups.iter().zip(positions) {
        render_summary_group(layout, group, x_mm, top_mm, 87.0, 34.0);
    }

    layout.text_at(
        LEFT_MM,
        31.0,
        &layout.paragraph(
            "Status values describe documentation and technical checks only; they are not a rights clearance or legal approval.",
        ),
        6.4,
        BuiltinFont::Helvetica,
    );
}

fn render_summary_group(
    layout: &mut PdfLayout,
    group: &OverviewGroup,
    x_mm: f32,
    top_mm: f32,
    width_mm: f32,
    height_mm: f32,
) {
    layout.box_outline(x_mm, top_mm, width_mm, height_mm, 0.3);
    layout.text_at(
        x_mm + 3.0,
        top_mm - 6.0,
        &layout.label(group.title),
        6.2,
        BuiltinFont::HelveticaBold,
    );
    let mut y_mm = top_mm - 13.0;
    for fact in group.facts.iter().take(4) {
        let label = layout.label(fact.label);
        let label_size = fit_text_size(&label, width_mm * 0.50, 5.8, 5.5, BuiltinFont::Helvetica);
        let label =
            ellipsize_text_to_width(&label, width_mm * 0.50, label_size, BuiltinFont::Helvetica);
        layout.text_at(x_mm + 3.0, y_mm, &label, label_size, BuiltinFont::Helvetica);
        let value = if fact.localize_value {
            layout.label(&fact.value)
        } else {
            fact.value.clone()
        };
        // The tone is already conveyed by the adjacent shape/color marker.
        // Repeating PASS/NOTICE/ERROR consumed the small summary value column
        // and forced otherwise readable German values into tiny type.
        let displayed = value;
        let value_x = x_mm + width_mm * 0.52;
        layout.status_icon_at(value_x, y_mm + 0.6, fact.tone);
        let value_width = width_mm * 0.47 - 4.8;
        let value_size = fit_text_size(
            &displayed,
            value_width,
            5.9,
            5.5,
            BuiltinFont::HelveticaBold,
        );
        let displayed = ellipsize_text_to_width(
            &displayed,
            value_width,
            value_size,
            BuiltinFont::HelveticaBold,
        );
        layout.status_text_at(
            value_x + 4.8,
            y_mm,
            &displayed,
            value_size,
            BuiltinFont::HelveticaBold,
            fact.tone,
        );
        y_mm -= 5.8;
    }
}

fn render_evidence_overview(layout: &mut PdfLayout, view: &CertificateViewModel<'_>) {
    layout.mark_bookmark("Evidence Overview", layout.current_page_index());
    layout.text_at(
        LEFT_MM,
        265.0,
        &layout.label("Evidence Overview"),
        14.0,
        BuiltinFont::HelveticaBold,
    );
    layout.rule(LEFT_MM, RIGHT_MM, 259.0, 0.6);
    layout.y_mm = 252.0;
    render_production_timeline(layout, view.snapshot);
    render_artwork_process_overview(layout, view.snapshot);
    render_audio_sampling_visualization(layout, &view.snapshot.track.audio_screening.external);

    layout.section_title("Screening and workflow snapshot");
    let local = &view.snapshot.track.audio_screening.local;
    let external = &view.snapshot.track.audio_screening.external;
    layout.table_rows(
        &[
            TableRow::system_plain("Chromaprint", audio_screening_status_label(local.status)),
            TableRow::system_plain("ACRCloud", audio_screening_status_label(external.status)),
            TableRow::provider_summary(
                "Provider response",
                &view.provider_response.response,
                view.provider_response.response_is_system,
            ),
            TableRow::provider_summary(
                "API version",
                &view.provider_response.api_version,
                view.provider_response.api_version_is_system,
            ),
            TableRow::plain(
                "Workflow checks",
                format!(
                    "{} PASS · {} N/A",
                    view.workflow_pass_count, view.workflow_na_count
                ),
            ),
        ],
        52.0,
    );
}

fn render_production_timeline(layout: &mut PdfLayout, snapshot: &CertificatePdfSnapshot<'_>) {
    layout.section_title("Track / production timeline");
    let fields = &snapshot.track.fields;
    let points = [
        ("Production start", fields.production_start_date.as_str()),
        (
            "Final generation",
            fields.suno_final_generation_date.as_str(),
        ),
        (
            "Technical finalization",
            snapshot
                .finalized_at
                .get(..10)
                .unwrap_or(snapshot.finalized_at),
        ),
    ]
    .into_iter()
    .filter_map(|(label, value)| parse_iso_date(value).map(|date| (label, value, date)))
    .collect::<Vec<_>>();
    let subscriptions = snapshot
        .evidence
        .iter()
        .filter(|item| item.role == EvidenceRole::SubscriptionPayment)
        .filter_map(|item| {
            let start_value = nonempty(item.coverage_start.as_deref())?;
            let end_value = nonempty(item.coverage_end.as_deref())?;
            Some((
                start_value,
                end_value,
                parse_iso_date(start_value)?,
                parse_iso_date(end_value)?,
            ))
        })
        .collect::<Vec<_>>();

    let mut all_dates = points.iter().map(|point| point.2).collect::<Vec<_>>();
    for range in &subscriptions {
        all_dates.extend([range.2, range.3]);
    }
    let Some(minimum) = all_dates.iter().min().copied() else {
        layout.write_localized(
            "Timeline not available — no documented dates",
            LEFT_MM,
            RIGHT_MM - LEFT_MM,
            7.0,
            BuiltinFont::Helvetica,
            1.3,
        );
        return;
    };
    let maximum = all_dates.iter().max().copied().unwrap_or(minimum);
    let axis_start = LEFT_MM + 8.0;
    let axis_width = RIGHT_MM - LEFT_MM - 16.0;
    // Keep the event ticks strictly proportional while moving only colliding
    // callouts onto separate vertical lanes. Closely spaced production dates
    // otherwise make both the date and event labels unreadable.
    let axis_y = layout.y_mm - 22.0;
    layout.rule(axis_start, axis_start + axis_width, axis_y, 0.55);
    let point_positions = points
        .iter()
        .map(|point| timeline_x(point.2, minimum, maximum, axis_start, axis_width))
        .collect::<Vec<_>>();
    let label_lanes = timeline_label_lanes(&point_positions);
    for (index, (label, value, _date)) in points.iter().enumerate() {
        let x = point_positions[index];
        layout.vertical_rule(x, axis_y + 2.0, axis_y - 2.0, 0.7);
        let label = layout.label(label);
        let label_size = fit_text_size(&label, 36.0, 5.7, 5.5, BuiltinFont::Helvetica);
        let label = ellipsize_text_to_width(&label, 36.0, label_size, BuiltinFont::Helvetica);
        let text_x = (x - 18.0).clamp(LEFT_MM, RIGHT_MM - 36.0);
        let date_y = axis_y + 19.0 - label_lanes[index] as f32 * 6.5;
        layout.text_at(text_x, date_y, value, 5.7, BuiltinFont::Courier);
        layout.text_at(
            text_x,
            date_y - 4.3,
            &label,
            label_size,
            BuiltinFont::Helvetica,
        );
    }
    let mut range_y = axis_y - 7.0;
    for (index, (start_value, end_value, start, end)) in subscriptions.iter().take(4).enumerate() {
        let from_x = timeline_x(*start, minimum, maximum, axis_start, axis_width);
        let to_x = timeline_x(*end, minimum, maximum, axis_start, axis_width);
        layout.rule(from_x, to_x.max(from_x + 0.8), range_y, 1.2);
        layout.text_at(
            axis_start,
            range_y - 4.0,
            &format!(
                "{} {}: {} – {}",
                layout.label("Subscription evidence"),
                index + 1,
                start_value,
                end_value
            ),
            5.5,
            BuiltinFont::Helvetica,
        );
        range_y -= 7.0;
    }
    layout.y_mm = if subscriptions.is_empty() {
        axis_y - 6.0
    } else {
        range_y - 1.0
    };
}

fn timeline_label_lanes(positions: &[f32]) -> Vec<usize> {
    const CALLOUT_WIDTH_MM: f32 = 38.0;
    const LANE_COUNT: usize = 3;

    let mut sorted = positions.iter().copied().enumerate().collect::<Vec<_>>();
    sorted.sort_by(|left, right| left.1.total_cmp(&right.1));
    let mut lanes = vec![0; positions.len()];
    let mut last_position_by_lane = [None; LANE_COUNT];
    for (original_index, position) in sorted {
        let lane = last_position_by_lane
            .iter()
            .position(|previous| {
                previous.is_none_or(|previous| position - previous >= CALLOUT_WIDTH_MM)
            })
            .unwrap_or(LANE_COUNT - 1);
        lanes[original_index] = lane;
        last_position_by_lane[lane] = Some(position);
    }
    lanes
}

fn render_artwork_process_overview(layout: &mut PdfLayout, snapshot: &CertificatePdfSnapshot<'_>) {
    let roles = [
        EvidenceRole::ArtworkSunoOriginal,
        EvidenceRole::AiArtworkOriginal,
        EvidenceRole::AiArtworkEdited,
        EvidenceRole::HumanEditedArtwork,
        EvidenceRole::FinalArtwork,
        EvidenceRole::ReleaseArtwork,
    ];
    let stages = roles
        .into_iter()
        .filter_map(|role| {
            snapshot
                .evidence
                .iter()
                .copied()
                .find(|item| item.role == role)
                .map(|item| (role, item))
        })
        .collect::<Vec<_>>();
    if stages.is_empty() {
        layout.section_title("Artwork process overview");
        layout.write_localized(
            "Artwork preview not available",
            LEFT_MM,
            RIGHT_MM - LEFT_MM,
            7.0,
            BuiltinFont::Helvetica,
            1.3,
        );
        return;
    }

    let gap_mm = 5.0;
    let stage_width =
        ((RIGHT_MM - LEFT_MM) - gap_mm * (stages.len() - 1) as f32) / stages.len() as f32;
    let maximum_name_lines = stages
        .iter()
        .map(|(_, item)| wrap_text(&item.file_name, stage_width, 5.5, BuiltinFont::Helvetica).len())
        .max()
        .unwrap_or(1);
    let stage_height = (51.0 + maximum_name_lines as f32 * 3.7).max(55.0);
    // Reserve the complete thumbnail/caption band plus its factual note so a
    // long file name cannot collide with the following audio section.
    layout.ensure_space(13.0 + stage_height + 10.0);
    layout.section_title("Artwork process overview");
    let top = layout.y_mm;
    for (index, (role, item)) in stages.iter().enumerate() {
        let x = LEFT_MM + index as f32 * (stage_width + gap_mm);
        let image_height = 28.0;
        if let Some(preview) = snapshot
            .artwork_previews
            .iter()
            .find(|preview| preview.role == *role)
        {
            layout.image_at(preview, x, top, stage_width, image_height);
        } else {
            layout.box_outline(x, top, stage_width, image_height, 0.35);
            let fallback = layout.label("Preview N/A");
            layout.text_at(
                x + 3.0,
                top - 14.0,
                &fallback,
                fit_text_size(
                    &fallback,
                    stage_width - 6.0,
                    6.0,
                    5.5,
                    BuiltinFont::HelveticaBold,
                ),
                BuiltinFont::HelveticaBold,
            );
        }
        let role_label = layout.label(artwork_role_label(*role));
        let role_size = fit_text_size(
            &role_label,
            stage_width,
            6.0,
            5.5,
            BuiltinFont::HelveticaBold,
        );
        let role_label = ellipsize_text_to_width(
            &role_label,
            stage_width,
            role_size,
            BuiltinFont::HelveticaBold,
        );
        layout.text_at(
            x,
            top - image_height - 5.0,
            &role_label,
            role_size,
            BuiltinFont::HelveticaBold,
        );
        let name_lines = wrap_text(&item.file_name, stage_width, 5.5, BuiltinFont::Helvetica);
        for (line_index, line) in name_lines.iter().enumerate() {
            layout.text_at(
                x,
                top - image_height - 10.0 - line_index as f32 * 3.7,
                line,
                5.5,
                BuiltinFont::Helvetica,
            );
        }
        if let Some(digest) = item.sha256.as_deref() {
            layout.text_at(
                x,
                top - image_height - 18.0 - name_lines.len() as f32 * 3.7,
                &abbreviated_sha256(digest),
                5.5,
                BuiltinFont::Courier,
            );
        }
        if index + 1 < stages.len() {
            layout.text_at(
                x + stage_width + 1.1,
                top - image_height / 2.0,
                ">",
                7.0,
                BuiltinFont::HelveticaBold,
            );
        }
    }
    layout.y_mm = top - stage_height;
    layout.write_localized(
        "Artwork images are visual previews only. Evidence ID, registered path, and full SHA-256 remain authoritative in the Evidence Register.",
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        6.2,
        BuiltinFont::Helvetica,
        1.25,
    );
}

fn render_audio_sampling_visualization(
    layout: &mut PdfLayout,
    external: &AudioScreeningExternalRecord,
) {
    layout.section_title("Audio sampling visualization");
    if external.samples.is_empty() {
        layout.table_row(
            &TableRow::system_plain(
                "External screening",
                audio_screening_status_label(external.status),
            ),
            44.0,
        );
        return;
    }
    let Some(duration) = external
        .source_duration_milliseconds
        .filter(|value| *value > 0)
    else {
        layout.write_localized(
            "Proportional visualization unavailable — source duration not documented.",
            LEFT_MM,
            RIGHT_MM - LEFT_MM,
            7.0,
            BuiltinFont::Helvetica,
            1.3,
        );
        render_audio_sampling_summary(layout, external);
        return;
    };
    let start_x = LEFT_MM + 4.0;
    let width = RIGHT_MM - LEFT_MM - 8.0;
    let axis_y = layout.y_mm - 9.0;
    layout.rule(start_x, start_x + width, axis_y, 0.6);
    layout.text_at(start_x, axis_y + 5.0, "0:00", 5.8, BuiltinFont::Courier);
    let end_label = friendly_milliseconds(duration);
    layout.text_at(
        start_x + width - 16.0,
        axis_y + 5.0,
        &end_label,
        5.8,
        BuiltinFont::Courier,
    );
    for sample in &external.samples {
        let ratio = (sample.offset_milliseconds.min(duration) as f64 / duration as f64) as f32;
        let x = start_x + ratio * width;
        layout.vertical_rule(x, axis_y + 2.7, axis_y - 2.7, 1.1);
    }
    layout.y_mm = axis_y - 7.0;
    render_audio_sampling_summary(layout, external);
}

fn render_audio_sampling_summary(layout: &mut PdfLayout, external: &AudioScreeningExternalRecord) {
    let status = audio_screening_status_label(external.status);
    let sample_summary = format!(
        "{} {} · {} {} · {} {}",
        external.unique_sample_count,
        layout.label("Unique samples"),
        external.duplicate_sample_count,
        layout.label("Duplicate samples"),
        external.overlapping_sample_count,
        layout.label("Overlapping samples"),
    );
    let sampled_duration = format!(
        "{} ms · {:.2} % {}",
        external.unique_sample_duration_milliseconds,
        external.track_coverage_percent,
        layout.label("track coverage"),
    );
    layout.table_rows(
        &[
            TableRow::plain("Sample summary", sample_summary),
            TableRow::plain("Sampled duration", sampled_duration),
            TableRow::system_plain("Overall result", status),
        ],
        44.0,
    );
}

fn render_full_technical_intro(layout: &mut PdfLayout) {
    layout.mark_bookmark("Full Technical Certificate", layout.current_page_index());
    render_document_title(layout);
    layout.write_localized(
        "The following A–L sections retain the complete technical certificate detail for audit and verification.",
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        7.2,
        BuiltinFont::Helvetica,
        1.3,
    );
    layout.y_mm -= 2.0;
}

fn abbreviated_sha256(value: &str) -> String {
    if value.len() <= 18 {
        return value.to_owned();
    }
    format!("{}…{}", &value[..8], &value[value.len() - 8..])
}

fn artwork_role_label(role: EvidenceRole) -> &'static str {
    match role {
        EvidenceRole::ArtworkSunoOriginal => "Suno original",
        EvidenceRole::AiArtworkOriginal => "AI original",
        EvidenceRole::AiArtworkEdited => "AI edited",
        EvidenceRole::HumanEditedArtwork => "Human edited",
        EvidenceRole::FinalArtwork => "Final",
        EvidenceRole::ReleaseArtwork => "Release artwork",
        _ => "Artwork",
    }
}

fn parse_iso_date(value: &str) -> Option<NaiveDate> {
    NaiveDate::parse_from_str(value, "%Y-%m-%d").ok()
}

fn timeline_x(
    value: NaiveDate,
    minimum: NaiveDate,
    maximum: NaiveDate,
    start_x: f32,
    width: f32,
) -> f32 {
    let total = (maximum - minimum).num_days().max(1) as f32;
    let offset = (value - minimum).num_days().max(0) as f32;
    start_x + (offset / total).clamp(0.0, 1.0) * width
}

fn friendly_milliseconds(value: u64) -> String {
    let total_seconds = value / 1_000;
    let minutes = total_seconds / 60;
    let seconds = total_seconds % 60;
    format!("{minutes}:{seconds:02}")
}

fn render_document_title(layout: &mut PdfLayout) {
    layout.write_localized(
        DOCUMENT_TITLE,
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        14.0,
        BuiltinFont::HelveticaBold,
        1.28,
    );
    layout.write_localized(
        "Finalized technical snapshot – not a legal certification",
        LEFT_MM,
        RIGHT_MM - LEFT_MM,
        7.5,
        BuiltinFont::Helvetica,
        1.2,
    );
    layout.y_mm -= 1.0;
    layout.rule(LEFT_MM, RIGHT_MM, layout.y_mm, 0.6);
    layout.y_mm -= 3.0;
}

